export type Text = {en:string;ru:string};
export const b = (en:string,ru:string):Text => ({en,ru});
export type Section = {title:Text;body:Text;formula?:string;source?:string};
const s = (en:string,ru:string,textEn:string,textRu:string,formula?:string,source?:string):Section => ({title:b(en,ru),body:b(textEn,textRu),formula,source});
export type Exercise = {id:string;prompt:Text;answer:Text;marks?:number;criterion?:string};
const q = (id:string,en:string,ru:string,answerEn:string,answerRu:string,marks?:number,criterion?:string):Exercise => ({id,prompt:b(en,ru),answer:b(answerEn,answerRu),marks,criterion});

export const supplements:Record<string,Section[]> = {
 'p-matter':[
  s('Internal energy, temperature and heating','Внутренняя энергия, температура и нагревание','Internal energy is the total microscopic kinetic and potential energy of a system. Temperature indicates its thermal state; in a simple particle model it is linked to average random kinetic energy. Heating transfers energy because of a temperature difference. A large cooler sample can have more internal energy than a small hotter sample. During a change of state, transferred energy can change particle separation and potential energy without raising temperature.','Внутренняя энергия складывается из энергии хаотического движения частиц и энергии их взаимодействия. Температура характеризует тепловое состояние: в школьной модели повышение температуры связано с ростом средней кинетической энергии движения частиц. Количество теплоты — энергия, переданная при теплообмене, а не вещество, содержащееся в теле. Поэтому большая масса прохладной воды может иметь большую внутреннюю энергию, чем маленькая масса горячей. При плавлении или кипении энергия расходуется на изменение взаимодействия частиц; температура чистого вещества при постоянном давлении остаётся постоянной.','Q = mcΔT; Q = mL','thermal'),
  s('Specific heat capacity and specific latent heat','Удельная теплоёмкость и удельная теплота','Specific heat capacity c is the energy needed per kilogram per kelvin of temperature increase, without a phase change. Specific latent heat L is the energy transferred per kilogram during a specified phase change at constant temperature. Use kilograms and distinguish a temperature difference from an absolute temperature. A heating curve has sloping regions for temperature change and idealised plateaux for phase changes. Real measured curves also reflect heat loss and impurities.','Удельная теплоёмкость показывает, какое количество теплоты требуется для нагревания 1 кг вещества на 1 °C без изменения агрегатного состояния. Единица: Дж/(кг·°C), равнозначно Дж/(кг·К) для разности температур. Удельная теплота плавления или парообразования — количество теплоты на 1 кг при соответствующем переходе. На школьном графике нагревания наклонный участок описывает изменение температуры, горизонтальный — фазовый переход. Если лёд сначала нагревают, затем плавят, затраты энергии считают отдельно и складывают.','c: J kg⁻¹ K⁻¹ · L: J kg⁻¹','thermal'),
  s('Pressure and the particle model','Давление в модели частиц','Gas pressure results from particles colliding with a surface and transferring momentum. At fixed volume, increasing absolute temperature increases average particle speed and pressure. At constant temperature for a fixed amount of gas, reducing volume increases pressure. Explain which variables are fixed before applying a relationship. A liquid is difficult to compress because its particles are already close together.','Давление газа возникает из-за ударов молекул о стенки. При неизменном объёме нагревание усиливает хаотическое движение и увеличивает давление. При постоянной температуре сжатие данной массы газа повышает давление. В каждом рассуждении сначала укажи, что сохраняется: масса газа, объём или температура. Нельзя говорить, что при нагревании «сами частицы стали больше». Жидкость плохо сжимается, поскольку расстояния между частицами уже малы.',undefined,'thermal'),
 ],
 'p-energy':[
  s('Energy, work, power and efficiency','Энергия, работа, мощность и КПД','Energy is conserved for the whole system, including its surroundings. Work is the energy transferred by a force as its point of application moves: W = Fd for a constant force parallel to the motion. Power is the rate of energy transfer; efficiency is the useful output divided by the total input, as a percentage. Dissipated energy is not destroyed: it spreads into the thermal stores of the surroundings and becomes less useful.','Энергия сохраняется для всей системы, включая окружающие тела. Работа (work) A (W) — это энергия, которую сила передаёт телу при перемещении точки её приложения. Для постоянной силы, направленной вдоль движения, A = Fs. Мощность — скорость передачи энергии; КПД — отношение полезной энергии к затраченной, выраженное в процентах. Рассеянная энергия не исчезает: она переходит во внутреннюю энергию (internal energy) окружающей среды и становится менее полезной.','Eₖ = ½mv²; ΔEₚ = mgΔh; Eₑ = ½kx²; P = W/t; η = useful/input × 100%','physics-book'),
 ],
 'p-electric':[
  s('Domestic safety and static charge','Электробезопасность и статическое электричество','A fuse melts when excessive current heats it, breaking the circuit. The earth wire provides a low-resistance fault path from an exposed metal case, allowing protection to disconnect the live supply. Double insulation prevents accessible parts becoming live without relying on an earth wire. Static charge is an imbalance of electrons: transfer of electrons leaves opposite charges; protons remain bound in nuclei. Discharge is charge moving through a conducting path, sometimes through ionised air.','Плавкий предохранитель разрывает цепь при чрезмерном токе: его проводник нагревается и плавится. Защитное заземление соединяет доступный металлический корпус с землёй, чтобы при повреждении изоляции сработала защита. Двойная изоляция отделяет доступные части от токоведущих. При электризации твёрдых тел перераспределяются электроны: потерявшее их тело заряжается положительно. Протоны при обычном трении из ядер не выходят. Разряд — движение заряда по проводящему пути, иногда через ионизированный воздух.',undefined,'physics-book'),
 ],
 'c-atoms':[
  s('Mendeleev and the periodic table','Менделеев и периодическая система','Mendeleev arranged the elements by atomic mass and recurring properties. He left gaps for undiscovered elements and predicted their properties. Elements in the same main group have the same number of outer electrons, so their chemical properties are similar. The table therefore helps predict how an element will behave.\n\nNoble gases are relatively unreactive because their outer shell is full.','Менделеев расположил элементы по атомным массам и повторяющимся свойствам. Он оставил пустые места для ещё не открытых элементов и предсказал их свойства. Элементы одной главной группы (main group) имеют одинаковое число внешних электронов, поэтому их химические свойства похожи. Благодаря этому по таблице можно предсказать поведение элемента.\n\nБлагородные газы (noble gases) довольно инертны, потому что их внешний электронный слой (outer shell) полностью заполнен.'),
 ],
 'c-bonds':[
  s('How structure determines properties','Как строение определяет свойства','Diamond is a giant covalent structure. Each carbon atom forms covalent bonds with four others, so the whole crystal is one strong network. This is why diamond is used in cutting and drilling tools. Every outer electron is used in a bond, so diamond does not conduct electricity.\n\nIn graphite, each carbon atom bonds to three others, forming flat layers. Weak forces hold the layers together, so they slide over each other. This makes graphite soft and useful as a dry lubricant. Unlike diamond, graphite conducts electricity along its layers, because each carbon atom has one delocalised electron that can move along them.\n\nGraphene is a single layer of graphite, only one atom thick.\n\nSimple molecular substances are made of separate molecules. In a carbon dioxide molecule (CO₂), the C=O covalent bonds are strong. Only weak intermolecular forces act between molecules. So carbon dioxide is a gas at room temperature.\n\n**Nanoparticles**\n\nNanoparticles are particles between 1 and 100 nm across. Smaller particles have a larger surface-area-to-volume ratio. More atoms sit at the surface, so nanoparticles can react more strongly. Their effects on health and the environment are not yet fully known.','Алмаз имеет атомную кристаллическую решётку (giant covalent structure). Каждый атом углерода связан с четырьмя соседями ковалентными связями (covalent bonds), и весь кристалл — одна прочная сетка. Поэтому алмаз применяют в режущих и бурильных инструментах. Все внешние электроны участвуют в связях, поэтому алмаз не проводит ток.\n\nВ графите каждый атом углерода связан с тремя соседями и входит в плоский слой. Слои удерживаются слабыми силами, поэтому они легко сдвигаются друг относительно друга. Из-за этого графит мягкий и служит сухой смазкой. В отличие от алмаза, он проводит ток вдоль слоёв, потому что у каждого атома углерода есть один делокализованный электрон (delocalised electron), который движется вдоль слоя.\n\nГрафен — это один слой графита толщиной в атом.\n\nВещества с молекулярным строением (simple molecular substances) состоят из отдельных молекул. В молекуле углекислого газа (CO₂) ковалентные связи C=O прочные. Между молекулами действуют только слабые межмолекулярные взаимодействия (intermolecular forces). Поэтому при комнатной температуре углекислый газ остаётся газом.\n\n**Наночастицы**\n\nНаночастицы (nanoparticles) — это частицы размером от 1 до 100 нм. Чем меньше частица, тем больше у неё отношение площади поверхности к объёму. На поверхности оказывается больше атомов, поэтому наночастицы могут реагировать активнее. Влияние таких частиц на организм и окружающую среду изучено пока не полностью.'),
 ],
 'c-quantity':[
  s('Atom economy and concentration','Атомная экономичность и концентрация','**Atom economy** is the mass of the desired product as a percentage of the total mass of all reactants in the balanced equation. It depends only on the equation, not on how well the experiment went.\n\nExample: 2H₂(g) + O₂(g) → 2H₂O(l). The reactants are 2 mol H₂ (4 g) and 1 mol O₂ (32 g), a total of 36 g. The desired product, 2 mol H₂O, also has a mass of 36 g. So atom economy = 36 ÷ 36 × 100% = 100%, because every reactant atom ends up in the product. However, the yield in the lab could still be low.\n\nMolar concentration is the amount of solute in moles per 1 dm³ of solution, in mol/dm³.','**Атомная экономичность** (atom economy) — масса нужного продукта в процентах от суммы масс всех реагентов по уравнению. Она зависит только от уравнения, а не от того, насколько удачно прошёл опыт.\n\nПример: 2H₂(г) + O₂(г) → 2H₂O(ж). Реагенты — 2 моль H₂ (4 г) и 1 моль O₂ (32 г), всего 36 г. Нужный продукт, 2 моль H₂O, тоже имеет массу 36 г. Поэтому атомная экономичность = 36 ÷ 36 × 100 % = 100 %: все атомы реагентов попадают в продукт. Но выход в лаборатории всё равно может быть низким.\n\nМолярная концентрация — это количество растворённого вещества в молях на 1 дм³ раствора, в моль/дм³.','yield = actual/theoretical × 100%; atom economy = desired product formula mass × coefficient / total reactant formula mass × coefficients × 100%; c = n/V'),
  s('Titration','Титрование','A titration finds an unknown concentration. A solution of known concentration is added from a burette until the reaction is complete (the equivalence point). The mole ratio from the balanced equation links the two amounts of substance.\n\nExample: 25.0 cm³ of NaOH reacts exactly with 20.0 cm³ of 0.100 mol/dm³ HCl. NaOH + HCl → NaCl + H₂O (1 : 1). n(HCl) = 0.100 mol/dm³ × 0.0200 dm³ = 2.00 × 10⁻³ mol; n(NaOH) = 2.00 × 10⁻³ mol; c(NaOH) = 2.00 × 10⁻³ mol ÷ 0.0250 dm³ = 0.0800 mol/dm³.','Титрование — метод определения неизвестной концентрации. Раствор известной концентрации добавляют из бюретки, пока реакция не закончится (точка эквивалентности). Отношение коэффициентов в уравнении реакции связывает количества веществ.\n\nПример: 25,0 см³ раствора NaOH полностью реагируют с 20,0 см³ раствора HCl с концентрацией 0,100 моль/дм³. NaOH + HCl → NaCl + H₂O (отношение 1 : 1). n(HCl) = 0,100 моль/дм³ × 0,0200 дм³ = 2,00 × 10⁻³ моль; n(NaOH) = 2,00 × 10⁻³ моль; c(NaOH) = 2,00 × 10⁻³ моль ÷ 0,0250 дм³ = 0,0800 моль/дм³.'),
 ],
 'c-changes':[
  s('Molten and aqueous electrolysis','Электролиз расплавов и растворов','Electrolysis uses electrical energy to drive a non-spontaneous reaction in an electrolyte. Positive ions gain electrons at the negative cathode: reduction. Negative ions lose electrons at the positive anode: oxidation. A molten salt contains its own ions; an aqueous solution also contains water-derived species, so products depend on competition and conditions. With inert electrodes, aqueous copper(II) sulfate deposits copper at the cathode and normally releases oxygen at the anode; concentrated sodium chloride solution commonly gives hydrogen and chlorine. Never apply molten-salt rules automatically to a solution.','Электролиз — окислительно-восстановительный процесс, протекающий под действием электрического тока. На катоде идёт восстановление, на аноде — окисление. В электролизёре катод отрицателен, анод положителен. В расплаве соли разряжаются её собственные ионы; в водном растворе с ними конкурируют частицы воды, поэтому продукты могут отличаться. Например, с инертными электродами раствор сульфата меди обычно даёт медь на катоде и кислород на аноде, а концентрированный раствор хлорида натрия — водород и хлор. Правила для расплава нельзя механически переносить на раствор.','Cu²⁺ + 2e⁻ → Cu; 2Cl⁻ → Cl₂ + 2e⁻','electrolysis'),
  s('Extracting aluminium and preparing salts','Алюминий и получение солей','Aluminium oxide is dissolved in molten cryolite, lowering the required operating temperature and helping conduction. Aluminium ions gain electrons at the cathode. Oxygen formed at carbon anodes reacts with the anodes, so they must be replaced. Electricity cost and carbon emissions are relevant impacts. To make a soluble salt from an acid and an insoluble base, add excess base, filter away the unreacted solid, then gently concentrate and crystallise the filtrate. Use titration when both reagents are soluble and excess reagent cannot be filtered off.','При получении алюминия оксид алюминия растворяют в расплавленном криолите: это позволяет снизить рабочую температуру и проводить электролиз. На катоде ионы алюминия принимают электроны. Кислород, образующийся у угольных анодов, реагирует с углеродом, поэтому аноды расходуются. Для получения растворимой соли из кислоты и нерастворимого основания добавляют избыток основания, отфильтровывают остаток, затем концентрируют раствор и выращивают кристаллы. Если оба реагента растворимы, лишний реагент фильтрованием не удалить; количество подбирают титрованием.','Al³⁺ + 3e⁻ → Al','electrolysis'),
 ],
 'c-energy':[
  s('Chemical cells and bond energies [H]','Химические источники тока и энергии связей [H]','A chemical cell turns chemical energy into electrical energy. The two metals in it differ in reactivity: the more reactive metal gives up electrons more easily. The bigger the gap in reactivity, the bigger the voltage. The size of the electrodes does not set the voltage. Some energy is always lost as heat.\n\nThe bond-energy method uses covalent bonds between atoms in molecules, such as H–H and Cl–Cl. Metals and ionic compounds are held together by metallic and ionic bonds, so the method is usually not suitable for a metal–ion cell reaction.','Гальванический элемент (химический источник тока, chemical cell) превращает химическую энергию в электрическую. Два металла в нём различаются по активности: более активный металл легче отдаёт электроны. Чем больше разница в активности, тем выше напряжение (voltage). Размер электродов на напряжение не влияет. Часть энергии всегда теряется в виде теплоты.\n\nМетод энергий связей (bond-energy method) опирается на ковалентные связи (covalent bonds) между атомами в молекулах, например, H–H и Cl–Cl. В металлах и ионных соединениях действуют металлическая и ионная связи (metallic, ionic bonds), поэтому метод обычно не подходит для типичной реакции в источнике тока с металлами и ионами.','ΔH ≈ ΣE(bonds broken) − ΣE(bonds formed)'),
 ],
 'c-rates':[
  s('Shifting dynamic equilibrium [H]','Смещение химического равновесия [H]','The position of equilibrium shifts when conditions change. One reaction runs faster for a while, so the composition changes until the forward and reverse rates are equal again.\n\n**Temperature:** raising it favours the endothermic direction.\n\n**Pressure:** raising it favours the side with fewer moles of gas. This applies only when the number of gas moles differs on the two sides.\n\n**Concentration:** adding a reactant favours the products, so some of the added reactant is used up.\n\nCommon mistake: rate and yield are different. A faster reaction does not give a higher yield.','Положение химического равновесия (dynamic equilibrium) смещается при изменении условий. Одна из реакций на время идёт быстрее другой, и состав меняется, пока скорости прямой и обратной реакций снова не станут равны.\n\n**Температура:** при нагревании равновесие смещается в сторону эндотермической (endothermic) реакции.\n\n**Давление:** при повышении давления равновесие смещается в сторону меньшего числа молей газа. Это действует только тогда, когда число молей газа слева и справа разное.\n\n**Концентрация (concentration):** при добавлении реагента равновесие смещается к продуктам, и часть добавленного реагента расходуется.\n\nНе путай скорость и выход (yield): быстрая реакция не даёт большего выхода.','N₂(g) + 3H₂(g) ⇌ 2NH₃(g) · forward reaction exothermic','equilibrium'),
 ],
 'b-nutrition':[
  s('Food tests and absorption','Пищевые пробы и всасывание','Food tests detect substances in a sample, not a person’s health. Iodine turns blue-black with starch. Benedict’s reagent, heated in a water bath, gives a coloured precipitate with reducing sugars. Biuret reagent turns lilac with protein. An ethanol emulsion test gives a cloudy white emulsion with lipids; ethanol is flammable. The ileum’s villi provide a large surface, thin exchange barrier and transport supply. Digestion hydrolyses large molecules; absorption moves small soluble products across the gut wall.','Качественные пищевые пробы показывают наличие вещества в образце. Йод даёт с крахмалом сине-чёрное окрашивание. Реактив Бенедикта после нагревания на водяной бане обнаруживает восстанавливающие сахара по окрашенному осадку. Биуретовая реакция выявляет белки фиолетовым окрашиванием. При эмульсионной пробе на жиры появляется белая муть; этанол огнеопасен. Ворсинки подвздошной кишки увеличивают поверхность всасывания, а тонкий эпителий сокращает путь переноса. Переваривание расщепляет крупные молекулы; всасывание переносит продукты через стенку кишечника.'),
 ],
 'b-plants':[
  s('Transpiration, translocation and a potometer','Транспирация, транспорт органики и потометр','Transpiration is loss of water vapour from aerial plant parts, mainly through stomata. Evaporation from mesophyll and diffusion out of the leaf create a pull on the xylem water column. Xylem carries water and mineral ions; phloem translocates organic solutes from sources to sinks and can carry them in different directions in different tubes. A potometer measures water uptake as a proxy for transpiration, not transpiration directly. Seal leaks, control leaf area, temperature and humidity, allow acclimatisation and repeat. Convert bubble distance to volume using tube cross-sectional area.','Транспирация — испарение воды растением, главным образом через устьица листьев. Испарение с поверхности клеток и выход водяного пара поддерживают движение воды по ксилеме. Ксилема переносит воду и минеральные соли; флоэма переносит органические вещества от источников к потребителям, причём направление в разных трубках может различаться. Потометром измеряют поглощение воды, которое используют как приближение к интенсивности транспирации. Проверь герметичность, сохраняй площадь листьев и внешние условия, дай побегу адаптироваться, проведи повторы. Часть поглощённой воды используется растением, поэтому величины не полностью совпадают.','volume uptake = πr² × bubble distance; rate = volume/time'),
 ],
 'b-biotech':[
  s('Genetic engineering, genome mapping and bioprinting','Генная инженерия, картирование генома и биопечать','Genetic engineering deliberately changes genetic material, for example inserting a useful gene into a plasmid vector and introducing it into bacteria. A genome is an organism’s complete genetic material. Genome mapping locates genetic markers or genes; sequencing determines base order. A sequence alone does not establish every gene’s function or predict every trait. Three-dimensional bioprinting places cells and supporting biomaterials in controlled patterns to build tissue-like structures. It differs from printing an inert plastic prosthesis. Challenges include cell survival, organisation and a blood supply; a printed tissue model is not automatically a functioning transplantable organ.','Генная инженерия целенаправленно изменяет наследственный материал. Например, нужный ген включают в плазмиду-вектор и вводят её в бактериальную клетку. Геном — совокупность наследственного материала организма. Картирование устанавливает расположение генов или маркеров, секвенирование — последовательность нуклеотидов; эти задачи связаны, но не тождественны. Знание последовательности само по себе не раскрывает все функции генов. При трёхмерной биопечати клетки и поддерживающие материалы располагают по заданной структуре для создания тканевых моделей. Это отличается от печати пластикового протеза. Нужно обеспечить жизнеспособность клеток и питание ткани; напечатанная модель ещё не равна готовому органу для пересадки.'),
 ],
 'b-nervous':[
  s('From stimulus to response','От раздражителя к ответу','A receptor detects a stimulus and converts it into a signal. In a withdrawal reflex, a sensory neurone carries impulses into the central nervous system, a relay neurone connects the pathway and a motor neurone activates an effector such as a muscle. Across a typical chemical synapse, neurotransmitter is released, diffuses and binds receptors on the next cell. The withdrawal can begin before conscious awareness; impulses also reach the brain. A reflex is a rapid, automatic response, not necessarily a response without the brain participating.','Рефлекс — ответ организма на раздражение при участии нервной системы. Рецептор воспринимает воздействие; чувствительный нейрон проводит возбуждение в центральную нервную систему; вставочный нейрон связывает участки дуги; двигательный нейрон передаёт сигнал исполнительному органу. В химическом синапсе медиатор выделяется, проходит через щель и связывается с рецепторами следующей клетки. При отдёргивании руки ответ может начаться до осознания боли, но информация также поступает в головной мозг. Не каждый рефлекс замыкается только в спинном мозге.','stimulus → receptor → sensory neurone → CNS → motor neurone → effector','reflex'),
  s('The eye: focusing and pupil reflex','Глаз: аккомодация и зрачковый рефлекс','The cornea provides much of the eye’s refraction; the lens adjusts focus so an image falls on the retina. Accommodation changes lens curvature. For a near object the ciliary muscle contracts, suspensory ligaments loosen and the lens becomes more convex. For a distant object the reverse occurs. The iris changes pupil diameter to regulate incoming light; it does not focus the image. In bright light circular iris muscles contract and the pupil narrows. Receptor cells in the retina convert light into signals carried towards the brain by the optic nerve.','Аккомодация — изменение кривизны хрусталика для получения чёткого изображения на сетчатке. При рассматривании близкого предмета ресничная мышца сокращается, натяжение связок ослабевает, хрусталик становится более выпуклым. Для далёкого предмета происходит обратное. Значительная часть преломления света приходится на роговицу. Радужка регулирует диаметр зрачка и количество поступающего света: при ярком освещении круговая мышца сокращается и зрачок сужается. Изменение зрачка и аккомодация — разные процессы. Фоторецепторы сетчатки преобразуют свет в нервные сигналы, поступающие по зрительному нерву. ',undefined,'eye'),
 ],
 'b-hormones':[
  s('Hormones and negative feedback','Гормоны и отрицательная обратная связь','An endocrine gland releases hormones into the circulation; target cells respond through suitable receptors. Negative feedback counteracts a change away from a regulated range. After a meal, pancreatic beta cells release insulin, promoting glucose uptake in responsive tissues and glycogen storage. When glucose falls, glucagon from alpha cells promotes glucose release by the liver. Adrenaline coordinates rapid responses to stress; thyroid hormones influence metabolic activity. Nervous and hormonal signalling can interact, so “fast versus slow” is a useful comparison rather than an absolute rule.','Железы внутренней секреции выделяют гормоны в кровь. Действие зависит от наличия у клеток соответствующих рецепторов. Отрицательная обратная связь уменьшает отклонение регулируемой величины. После еды инсулин способствует поступлению глюкозы в чувствительные ткани и её запасанию; при снижении глюкозы глюкагон способствует её образованию и выходу из печени. Адреналин участвует в быстром приспособлении к нагрузке, гормоны щитовидной железы влияют на интенсивность обмена. Нервная и гормональная регуляция связаны; сравнение «быстро — медленно» полезно, но не является правилом без исключений.',undefined,'endocrine'),
  s('The menstrual cycle: linked ovarian and uterine changes','Менструальный цикл: яичник и матка','The cycle coordinates follicle development and changes in the uterine lining. FSH promotes follicle development; the developing follicle produces oestrogens, which support rebuilding of the lining. A sustained high oestrogen level contributes to an LH surge triggering ovulation. The corpus luteum produces progesterone, helping maintain the lining. If pregnancy does not occur, falling progesterone and oestrogen levels lead to menstruation. A 28-day diagram is a teaching model: real timing varies, and ovulation is not universally on day 14.','Менструальный цикл объединяет изменения в яичнике и слизистой оболочке матки. ФСГ способствует развитию фолликула; его эстрогены поддерживают восстановление эндометрия. Высокий уровень эстрогенов участвует в запуске выброса ЛГ и овуляции. После овуляции жёлтое тело вырабатывает прогестерон, который поддерживает эндометрий. Если беременность не наступила, снижение прогестерона и эстрогенов приводит к менструации. Схема на 28 дней — учебная модель: длительность и момент овуляции могут различаться.','FSH → follicle; LH surge → ovulation; progesterone → maintained lining','cycle'),
  s('Auxin and directional growth','Ауксины и направленный рост','A tropism is a directional growth response. In the simplified shoot model, unilateral light produces a difference in auxin action across the shoot; greater elongation on the shaded side bends it towards light. A growth response differs from a rapid muscular movement. Auxin also influences roots, but roots and shoots respond differently to concentration, so do not apply the shoot rule indiscriminately. Gibberellins can promote germination and stem growth; plant hormones regulate interacting processes, not one isolated “job” each.','Тропизм — направленная ростовая реакция растения на действие раздражителя. В школьной модели фототропизма побега ауксины вызывают неодинаковое удлинение клеток: затенённая сторона растёт сильнее, и побег изгибается к свету. Это рост, а не сокращение мышц. Корни и побеги по-разному чувствительны к концентрации ауксина, поэтому правило для побега нельзя без проверки переносить на корень. Гиббереллины могут стимулировать прорастание и рост стебля. Фитогормоны действуют совместно и участвуют в нескольких процессах.'),
 ],
 'b-earlier':[
  s('Human reproduction and development','Размножение и развитие человека','Sperm and egg cells are haploid gametes; fertilisation combines their genetic material into a diploid zygote, usually in an oviduct. Cell divisions produce an embryo, which implants in the uterine lining. The placenta provides an exchange surface for oxygen, nutrients and wastes between maternal and fetal circulations without normal direct mixing of their blood; some harmful substances can cross. In IVF, fertilisation occurs outside the body before an embryo is transferred to the uterus. Puberty includes hormone-regulated maturation; testosterone and oestrogens influence development, with functions in all sexes.','При оплодотворении объединяется наследственный материал мужской и женской гамет и образуется диплоидная зигота. Обычно это происходит в маточной трубе. После делений зародыш внедряется в эндометрий; имплантация отличается от оплодотворения. Через плаценту происходит обмен газами, питательными веществами и продуктами обмена между организмами матери и плода; их кровь в норме прямо не смешивается. Плацента пропускает и некоторые вредные вещества. При ЭКО оплодотворение проводят вне организма, затем переносят эмбрион в матку. Половое созревание регулируется гормонами и включает созревание репродуктивной системы.',undefined,'human-reproduction'),
  s('Flowers, seeds and germination','Цветок, семя и прорастание','Anthers produce pollen; a stigma receives it. Pollination transfers pollen from anther to stigma. A pollen tube grows towards an ovule, allowing a male nucleus to fuse with the egg nucleus: fertilisation. The ovule develops into a seed and the ovary commonly forms the fruit. Dispersal reduces competition near the parent. Germination generally requires water, oxygen and a suitable temperature; light requirements depend on the species. The embryo respires using stored food before photosynthesis supplies enough new carbohydrate.','Опыление — перенос пыльцы из пыльника на рыльце пестика. После него прорастает пыльцевая трубка, по которой мужские половые клетки достигают семязачатка. Слияние с яйцеклеткой даёт зиготу; у цветковых также происходит второе слияние, образующее зачаток питательной ткани. Из семязачатка развивается семя, из завязи обычно формируется плод. Распространение семян снижает конкуренцию с родительским растением. Для прорастания нужны вода, кислород и подходящая температура; потребность в свете зависит от вида. Вначале зародыш расходует запасённые вещества на дыхание и рост.',undefined,'plant-reproduction'),
  s('Bones, joints and antagonistic muscles','Кости, суставы и мышцы-антагонисты','The skeleton supports the body, protects organs and provides levers for movement. At a synovial joint, cartilage reduces friction and absorbs loads; synovial fluid lubricates; ligaments connect bone to bone. Tendons connect muscle to bone. A skeletal muscle generates tension by contraction and cannot actively push a bone back. Antagonistic pairs coordinate opposite movements: elbow flexion involves biceps contraction, while extension involves triceps contraction. Both may be active to stabilise a joint.','Скелет служит опорой, защищает органы и участвует в движении как система рычагов. Суставной хрящ уменьшает трение и распределяет нагрузку, синовиальная жидкость смазывает поверхности, связки соединяют кости. Сухожилия прикрепляют мышцы к костям. Мышца создаёт тягу при сокращении, но не может активно толкнуть кость обратно. Поэтому противоположные движения обеспечивают мышцы-антагонисты: сгибанию локтя способствует двуглавая мышца, разгибанию — трёхглавая. При удержании сустава они могут работать одновременно.'),
 ],
 'e-creative':[
  s('Drama as a text for performance','Драма как текст для исполнения','A drama is written to be performed. Its dialogue and stage directions give actors choices, and the audience sees or hears the result. A stage direction is the author’s note on action, tone of voice, movement or sound, for example: [Mara sits down and picks up a pen.] A monologue is a long speech by one speaker, who develops a thought or feeling and may address a listener, the audience or themselves. Pauses, movement, sound and lighting shape how the audience reads a moment, so explain what each choice does, not just what it is called.','Драма — текст, который пишут для исполнения на сцене. Реплики и ремарки (stage directions) дают актёру выбор, а зритель видит или слышит результат. Ремарка — авторское пояснение о действии, интонации, движении или звуке, например: [Мара садится за стол и берёт ручку.] Монолог — длинная речь одного говорящего, в которой раскрываются мысли или переживания героя. Он может обращаться к собеседнику, зрителю или к самому себе. Пауза, движение, звук и свет влияют на то, как зритель понимает момент, поэтому объясняй, что даёт каждый выбор, а не только называй его.',undefined,'english-book'),
 ],
 'e-purpose':[
  s('Purpose determines form','Цель определяет форму','Before writing, identify audience, purpose, situation and the requested text type. An article needs a clear angle, purposeful paragraphs and an ending that develops the point. A letter uses an appropriate address and register. A diary creates a credible private perspective. A blog can address readers directly. A speech should sound speakable and build towards an appeal. A narrative needs a controlled viewpoint and a meaningful sequence of events. Text-type conventions support communication; decorative features alone do not fulfil the task.','Перед началом письма определи адресата, цель, ситуацию и требуемый жанр. В статье нужен ясный вопрос и связное развитие мысли; в письме — уместное обращение и стиль; в дневнике — убедительная личная перспектива; в блоге — обращение к читателю; в речи — произносимые фразы и логика убеждения; в рассказе — выбранная точка зрения и осмысленная последовательность событий. Формальные признаки помогают выполнить коммуникативную задачу, но одни заголовки и обращения её не заменяют.'),
 ],
 's-b':[
  s('A reproducible investigation','Воспроизводимое исследование','Specify how the independent variable is changed and how the dependent variable is measured, including units and an appropriate range. A hypothesis predicts a relationship and explains a mechanism. Controls isolate plausible alternative causes. A method states quantities, apparatus, timing, repeats and a safety measure tied to a real hazard. Repeats estimate variation; they do not remove a systematic bias.','Исследовательский вопрос связывает изменяемую величину с измеряемым результатом. Укажи единицы, диапазон и способ измерения. Гипотеза содержит прогноз и научное объяснение. Контролируемые переменные помогают исключить другие причины результата. Метод должен позволять повторить опыт: количества, приборы, время, повторы и мера безопасности для конкретной опасности. Повторение оценивает разброс, но не исправляет систематическую ошибку прибора.'),
 ],
 's-c':[
  s('Evidence, uncertainty and improvement','Данные, неопределённость и улучшение','A conclusion answers the research question using processed data and a mechanism; it should acknowledge scatter, anomalies and the tested range. A negative correlation is not automatically inverse proportionality. Direct proportionality requires a constant ratio and an appropriate zero, not merely an increasing line. Distinguish random variation from systematic bias. Link each improvement to a named limitation and explain how it changes the evidence.','Вывод отвечает на исследовательский вопрос, опирается на обработанные данные и объясняет механизм. Учитывай разброс, необычные результаты и проверенный диапазон. Убывание одной величины при росте другой ещё не доказывает обратную пропорциональность. Для прямой пропорциональности нужно постоянное отношение и соответствующее начало отсчёта. Случайный разброс отличается от систематического смещения. Улучшение должно устранять конкретный недостаток; объясни, как именно оно повысит качество данных.'),
 ],
 's-d':[
  s('Evaluate an application of science','Оценка применения науки','Explain the science, then connect a benefit and a limitation to evidence in the task. Consider who gains, who bears costs and which conditions matter. A justified conclusion weighs the evidence rather than counting advantages. Separate a measured result from an extrapolation and state uncertainty where the data do not decide the question. Do not invent a percentage or cite an unnamed “study”.','Сначала объясни научный механизм, затем свяжи пользу и ограничение с данными задания. Укажи, кто получает преимущество, кто несёт издержки и от каких условий зависит результат. Обоснованный вывод оценивает силу доказательств, а не просто считает плюсы и минусы. Различай измеренный результат и предположение о будущем. Если данных недостаточно, назови неопределённость. Нельзя придумывать проценты или ссылаться на неназванное «исследование».'),
 ],
};

export const practice:Record<string,Exercise[]> = {
 'p-atom':[q('isotope','A neutral atom has Z = 17 and A = 37. State its particle counts; then describe the change when it becomes a 1− ion.','У нейтрального атома Z = 17, A = 37. Найди числа частиц и объясни изменение при образовании иона 1−.','17 protons, 20 neutrons, 17 electrons. It gains one electron: 18 electrons; nucleus unchanged.','17 протонов, 20 нейтронов, 17 электронов. Ион получает электрон: их 18; ядро не меняется.',4),q('halflife','Background is 20 counts/min. A source plus background falls from 820 to 120 counts/min in 18 min. Find its half-life.','Фон 20 имп/мин. Суммарный счёт уменьшается с 820 до 120 имп/мин за 18 мин. Найди период полураспада.','Subtract background: 800 → 100. This is three halvings, so t½ = 18/3 = 6 min.','После вычитания фона: 800 → 100. Три уменьшения вдвое; T½ = 18/3 = 6 мин.',4)],
 'p-energy':[q('lift','A motor lifts a 15 kg load by 2.0 m in 4.0 s. The motor receives 500 J of energy. Take g ≈ 10 N/kg (rounded). Calculate the useful energy, the useful power and the efficiency of the motor.','Двигатель поднимает груз массой 15 кг на 2,0 м за 4,0 с и получает 500 Дж энергии. Прими g ≈ 10 Н/кг (округлённо). Вычисли полезную энергию, полезную мощность и КПД двигателя.','Useful energy: E = mgh = 15 kg × 10 N/kg × 2.0 m = 300 J. Useful power: P = E / t = 300 J / 4.0 s = 75 W. Efficiency = useful energy / total energy × 100% = 300 J / 500 J × 100% = 60%. The remaining 200 J (500 J − 300 J) is transferred to other stores, mainly internal energy of the motor and its surroundings.','Полезная энергия: Eпол = mgh = 15 кг × 10 Н/кг × 2,0 м = 300 Дж. Полезная мощность: Nпол = Eпол / t = 300 Дж / 4,0 с = 75 Вт. КПД = Eпол / Eзат × 100 % = 300 Дж / 500 Дж × 100 % = 60 %. Остальные 200 Дж (500 Дж − 300 Дж) переходят в другие виды энергии, в основном во внутреннюю энергию двигателя и окружающей среды.',6)],
 'p-matter':[q('ice','How much energy warms 0.20 kg of ice from −10°C to 0°C and melts it? cice = 2100 J/(kg K), L = 334000 J/kg. Ignore losses.','Сколько энергии нужно для нагревания 0,20 кг льда от −10 до 0 °C и плавления? cльда = 2100 Дж/(кг·К), L = 334000 Дж/кг. Потерями пренебречь.','Warming: 0.20 × 2100 × 10 = 4200 J. Melting: 0.20 × 334000 = 66800 J. Total 71000 J. Temperature does not rise during the idealised melting stage.','Нагревание: 4200 Дж; плавление: 66800 Дж; всего 71000 Дж. Во время плавления температура в этой модели не растёт.',5)],
 'p-electric':[q('parallel','Two resistors, 6 Ω and 3 Ω, are in parallel across 12 V. Find each current, total current and equivalent resistance.','Резисторы 6 Ом и 3 Ом параллельно подключены к 12 В. Найди токи ветвей, общий ток и сопротивление.','Each branch has 12 V. I₁ = 12/6 = 2 A; I₂ = 12/3 = 4 A. Total 6 A; Req = 12/6 = 2 Ω.','На каждой ветви 12 В. Токи: 2 А и 4 А. Общий ток 6 А; R = 12/6 = 2 Ом.',5),q('fuse','Explain why a metal-cased appliance needs protection if the live wire touches its case.','Объясни назначение защиты, если фазный провод коснулся металлического корпуса прибора.','The case could be at a dangerous potential. An earth path allows a fault current to operate the fuse or circuit breaker and disconnect the supply. The fuse belongs in the live conductor.','Корпус может оказаться под опасным напряжением. Заземление создаёт путь тока повреждения, чтобы сработал предохранитель или автомат и отключил питание. Предохранитель устанавливают в фазный провод.',3)],
 'p-forces':[q('momentum','A 0.40 kg trolley moving at 3.0 m/s couples to a stationary 0.80 kg trolley. Find their common velocity if external impulse is negligible. Explain what is not conserved.','Тележка 0,40 кг со скоростью 3,0 м/с сцепляется с неподвижной тележкой 0,80 кг. Внешним импульсом пренебречь. Найди скорость и укажи, что не сохраняется.','Momentum: 0.40 × 3.0 = (0.40 + 0.80)v, so v = 1.0 m/s in the original direction. Kinetic energy falls from 1.8 J to 0.6 J; some energy becomes internal energy and sound. Total energy is conserved.','0,40 × 3,0 = 1,20v, значит v = 1,0 м/с в прежнем направлении. Кинетическая энергия уменьшается с 1,8 до 0,6 Дж; часть переходит во внутреннюю энергию и звук. Полная энергия сохраняется.',6),q('moment','A 30 N force acts perpendicular to a lever 0.20 m from the pivot. Find its moment. What force at 0.15 m balances it?','Сила 30 Н перпендикулярна рычагу на расстоянии 0,20 м от оси. Найди момент и уравновешивающую силу на плече 0,15 м.','Moment = 30 × 0.20 = 6.0 N m. Balancing force = 6.0/0.15 = 40 N, producing an opposite rotational effect.','Момент 6,0 Н·м. F = 6,0/0,15 = 40 Н; направление создаёт противоположный вращательный эффект.',4)],
 'p-waves':[q('wave','A wave has frequency 250 Hz and wavelength 1.2 m. Find speed. Explain what changes when light enters glass from air.','Частота волны 250 Гц, длина 1,2 м. Найди скорость. Что меняется при переходе света из воздуха в стекло?','v = fλ = 300 m/s. In ordinary glass light slows; frequency remains the same, so wavelength decreases. It bends towards the normal unless incident normally.','v = fλ = 300 м/с. В стекле свет распространяется медленнее, частота сохраняется, длина волны уменьшается. При наклонном падении луч отклоняется к нормали.',5)],
 'c-atoms':[q('ar','A simplified sample of chlorine contains 75% ³⁵Cl and 25% ³⁷Cl. Calculate its relative atomic mass, Ar, and explain why the two isotopes react in a similar way.','В упрощённом образце хлора 75 % приходится на ³⁵Cl и 25 % — на ³⁷Cl. Рассчитай относительную атомную массу (relative atomic mass) Ar и объясни, почему эти изотопы (isotopes) реагируют похожим образом.','Ar = (0.75 × 35) + (0.25 × 37) = 26.25 + 9.25 = 35.5. Multiply each mass number by its share in the sample, then add the results. Both isotopes have 17 protons, so neutral atoms of both have the same electron arrangement and the same outer electrons. Their chemical properties are therefore similar.','Ar = (0,75 × 35) + (0,25 × 37) = 26,25 + 9,25 = 35,5. Каждое массовое число (mass number) умножь на долю изотопа в образце и сложи результаты. У обоих изотопов по 17 протонов, поэтому у нейтральных атомов одинаковая электронная конфигурация (electron configuration) и одинаковое число внешних электронов. Значит, химические свойства изотопов похожи.',4),q('separate','Describe how to separate a mixture of sand, salt and water to recover dry sand and dry salt.','Опиши, как разделить смесь (mixture) песка, соли и воды, чтобы получить сухой песок и сухую соль.','Filter the mixture: the sand stays on the filter paper. Wash the sand with a little water, add the washings to the filtrate and dry the sand. Carefully evaporate the water from the filtrate to dryness, which leaves the salt. Dissolved salt passes through the filter paper, so the salt is recovered by evaporation instead.','Отфильтруй (filter) смесь: песок останется на фильтре. Промой песок небольшим количеством воды, промывную воду добавь к фильтрату и высуши песок. Осторожно выпари воду из фильтрата досуха: останется соль. Растворённая соль проходит через фильтр, поэтому её выделяют выпариванием, а не фильтрованием.',4)],
 'c-bonds':[q('structure','Explain why solid sodium chloride does not conduct electricity but molten sodium chloride does. Compare this with graphite, which conducts electricity even as a solid.','Объясни, почему твёрдый хлорид натрия (NaCl) не проводит ток, а расплавленный проводит. Сравни с графитом, который проводит ток даже в твёрдом виде.','Conduction needs charged particles that can move.\n\nSolid sodium chloride: the Na⁺ and Cl⁻ ions are fixed in a lattice, so they cannot carry charge.\n\nMolten sodium chloride: melting breaks the lattice, so the ions move and carry charge.\n\nGraphite: each carbon atom has one delocalised electron that moves along the layer, so solid graphite conducts.\n\nCommon mistake: molten sodium chloride does not contain free electrons. Its charge carriers are ions.','Для проводимости нужны заряженные частицы, которые могут двигаться.\n\nТвёрдый хлорид натрия: ионы Na⁺ и Cl⁻ закреплены в ионной кристаллической решётке (ionic lattice), поэтому они не переносят заряд.\n\nРасплав: плавление разрушает ионную кристаллическую решётку, ионы начинают двигаться и переносят заряд.\n\nГрафит: у каждого атома углерода есть один делокализованный электрон (delocalised electron), который движется вдоль слоя. Поэтому твёрдый графит проводит ток.\n\nЧастая ошибка: не думай, что в расплаве хлорида натрия есть делокализованные электроны. Носители заряда в нём — ионы.',4)],
 'c-quantity':[q('moles','Calcium carbonate decomposes when heated: CaCO₃(s) → CaO(s) + CO₂(g). Use Ar: Ca = 40, C = 12, O = 16. From 10.0 g of CaCO₃:\n\n(a) calculate the theoretical mass of CaO.\n\n(b) calculate the percentage yield if 4.48 g of CaO is obtained.\n\n(c) calculate the atom economy for CaO.','Карбонат кальция при нагревании разлагается: CaCO₃(тв) → CaO(тв) + CO₂(г). Ar: Ca = 40, C = 12, O = 16. Из 10,0 г карбоната кальция:\n\nа) рассчитай теоретическую массу оксида кальция.\n\nб) рассчитай выход продукта (percentage yield), если получено 4,48 г оксида кальция.\n\nв) рассчитай атомную экономичность (atom economy) для оксида кальция.','(a) Step 1: M(CaCO₃) = 100 g/mol, so n(CaCO₃) = m/M = 10.0 g ÷ 100 g/mol = 0.100 mol.\n\nStep 2: from CaCO₃(s) → CaO(s) + CO₂(g), the ratio is 1 : 1, so n(CaO) = 0.100 mol.\n\nStep 3: M(CaO) = 56 g/mol, so m(CaO) = nM = 0.100 mol × 56 g/mol = 5.60 g. This is the theoretical mass.\n\n(b) Percentage yield = 4.48 g ÷ 5.60 g × 100% = 80%.\n\n(c) Atom economy = M(CaO) ÷ M(CaCO₃) × 100% = 56 ÷ 100 × 100% = 56%.','а) Шаг 1: M(CaCO₃) = 100 г/моль, значит n(CaCO₃) = m/M = 10,0 г ÷ 100 г/моль = 0,100 моль.\n\nШаг 2: по уравнению CaCO₃(тв) → CaO(тв) + CO₂(г) отношение 1 : 1, поэтому n(CaO) = 0,100 моль.\n\nШаг 3: M(CaO) = 56 г/моль, значит m(CaO) = nM = 0,100 моль × 56 г/моль = 5,60 г — это теоретическая масса.\n\nб) Выход продукта = 4,48 г ÷ 5,60 г × 100 % = 80 %.\n\nв) Атомная экономичность = M(CaO) ÷ M(CaCO₃) × 100 % = 56 ÷ 100 × 100 % = 56 %.',8),q('concentration','A solution contains 0.050 mol of solute in 250 cm³ of solution. Calculate its amount concentration in mol/dm³.','В 250 см³ раствора содержится 0,050 моль растворённого вещества (solute). Рассчитай молярную концентрацию (amount concentration) раствора в моль/дм³.','First convert the volume to dm³: 250 cm³ ÷ 1000 = 0.250 dm³. Then c = n/V = 0.050 mol ÷ 0.250 dm³ = 0.20 mol/dm³.','Сначала переведи объём в дм³: 250 см³ ÷ 1000 = 0,250 дм³. Затем c = n/V = 0,050 моль ÷ 0,250 дм³ = 0,20 моль/дм³.',3)],
 'c-changes':[q('electrolysis','Write the electrode half-equations for molten lead(II) bromide. Explain why liquid is necessary.','Запиши полуреакции электролиза расплава бромида свинца(II). Почему нужен расплав?','Cathode: Pb²⁺ + 2e⁻ → Pb. Anode: 2Br⁻ → Br₂ + 2e⁻. Melting frees ions to move and carry charge through the electrolyte.','Катод: Pb²⁺ + 2e⁻ → Pb. Анод: 2Br⁻ → Br₂ + 2e⁻. В расплаве ионы подвижны и проводят ток.',5),q('salt','Describe preparation of pure copper sulfate crystals from dilute sulfuric acid and copper oxide.','Опиши получение чистых кристаллов сульфата меди из разбавленной серной кислоты и оксида меди.','Warm acid gently, add CuO in portions until excess remains, filter off excess solid, gently evaporate some water and cool to crystallise. Separate and dry crystals. CuO + H₂SO₄ → CuSO₄ + H₂O. Eye protection and careful handling of hot acid.','Осторожно нагрей кислоту, порциями добавь CuO до избытка, отфильтруй остаток. Частично выпари воду, охлади, отдели и высуши кристаллы. CuO + H₂SO₄ → CuSO₄ + H₂O. Нужны защитные очки и осторожность с горячей кислотой.',6)],
 'c-energy':[q('bonds','Use the bond energies H–H 436, Cl–Cl 243 and H–Cl 431 kJ/mol to estimate ΔH for H₂(g) + Cl₂(g) → 2HCl(g). Give your answer in kJ/mol, with its sign, for the equation as written. [H]','Используй энергии связей (bond energies) H–H 436, Cl–Cl 243 и H–Cl 431 кДж/моль, чтобы оценить ΔH для реакции H₂(г) + Cl₂(г) → 2HCl(г). Ответ запиши в кДж/моль со знаком (для уравнения, как оно написано). [H]','Energy needed to break bonds: H–H + Cl–Cl = 436 + 243 = 679 kJ/mol.\n\nEnergy released when bonds form: 2 × H–Cl = 2 × 431 = 862 kJ/mol.\n\nΔH ≈ 679 − 862 = −183 kJ/mol for the equation as written. The negative sign means the reaction is exothermic.\n\nSome tables give 242 kJ/mol for Cl–Cl; then ΔH ≈ −184 kJ/mol. The small difference is normal for average bond energies.','На разрыв связей H–H и Cl–Cl нужно 436 + 243 = 679 кДж/моль.\n\nПри образовании двух связей H–Cl выделяется 2 × 431 = 862 кДж/моль.\n\nΔH ≈ 679 − 862 = −183 кДж/моль (для уравнения, как оно записано). Знак минус означает, что реакция экзотермическая (exothermic).\n\nВ некоторых таблицах Cl–Cl — 242 кДж/моль; тогда ΔH ≈ −184 кДж/моль. Небольшая разница нормальна для средних энергий связей.',5)],
 'c-rates':[q('equilibrium','For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the forward reaction is exothermic. Predict how higher pressure, higher temperature and a catalyst affect the equilibrium yield of ammonia [H].','Для N₂(g) + 3H₂(g) ⇌ 2NH₃(g) прямая реакция экзотермическая (exothermic). Предскажи, как повышение давления, повышение температуры и катализатор (catalyst) повлияют на равновесный выход (equilibrium yield) аммиака [H].','Work through each change. Pressure: the left side has 1 + 3 = 4 mol of gas and the right side has 2 mol, so higher pressure favours the right side and the ammonia yield rises. Temperature: the forward reaction is exothermic, so the reverse reaction is endothermic; higher temperature favours the reverse direction and the equilibrium yield falls. Catalyst: it speeds up the forward and reverse reactions equally, so equilibrium is reached sooner, but the yield does not change.','Разбери каждое изменение. Давление: слева 1 + 3 = 4 моль газа, справа 2 моль, поэтому повышение давления смещает равновесие вправо, и выход аммиака растёт. Температура: прямая реакция экзотермическая, значит, обратная реакция эндотермическая; нагревание смещает равновесие к обратной реакции, и равновесный выход уменьшается. Катализатор: он одинаково ускоряет прямую и обратную реакции, поэтому равновесие наступает быстрее, но выход не меняется.',6)],
 'c-air':[q('climate','Distinguish CO₂, CO, SO₂ and particulates from combustion. Give a consequence of each without treating every pollutant as the same.','Различи CO₂, CO, SO₂ и сажу при сгорании. Назови по одному последствию, не смешивая все загрязнители.','CO₂ strengthens the greenhouse effect; CO interferes with oxygen transport in blood; SO₂ contributes to acid deposition and respiratory irritation; particulates affect breathing and can alter radiation balance. Complete hydrocarbon combustion forms CO₂ and water; incomplete combustion can form CO and soot.','CO₂ усиливает парниковый эффект; CO нарушает перенос кислорода кровью; SO₂ способствует кислотным выпадениям и раздражению дыхательных путей; частицы вредят дыханию и влияют на радиационный баланс. Неполное сгорание может давать CO и сажу.',6)],
 'b-cells':[q('magnification','A microscope image shows a cell 36 mm long. The cell’s actual length is 60 μm. Calculate the magnification and explain why a higher magnification does not always reveal more detail.','На снимке с микроскопа клетка имеет длину 36 мм, а её реальная длина — 60 мкм. Найди увеличение и объясни, почему большее увеличение не всегда показывает больше деталей.','36 mm = 36 000 μm. Magnification = image size / actual size = 36 000 μm / 60 μm = ×600. Resolution is the smallest distance at which two close points can still be seen as separate. Higher magnification only makes the image bigger; if the image is blurred, enlarging it adds no new detail.','36 мм = 36 000 мкм. Увеличение = размер изображения / реальный размер = 36 000 мкм / 60 мкм = ×600. Предел разрешения (resolution) — наименьшее расстояние, при котором две близкие точки видны раздельно. Большее увеличение только делает изображение крупнее; если оно размытое, увеличение не добавляет новых деталей.',4),q('osmosis','Potato cylinders gain 8% of their mass in a dilute solution. Explain this result using osmosis. Suggest one variable that must be kept the same to make the test fair.','Картофельные цилиндры в разбавленном растворе увеличили массу на 8 %. Объясни этот результат через осмос. Предложи одну переменную, которую нужно сохранять постоянной, чтобы опыт был корректным.','Water moves into the potato cells by osmosis. It passes through partially permeable membranes from the dilute solution (higher water potential) into the cells (lower water potential, because they hold more dissolved solutes), so the cells gain water and their mass increases. One suitable control variable is the starting size of the cylinders. Keep the immersion time and temperature the same too, and blot each cylinder in the same way before weighing.','Вода поступает в клетки картофеля за счёт осмоса (osmosis). Она проходит через полупроницаемые мембраны (partially permeable membranes) из разбавленного раствора, где водный потенциал (water potential) выше, в клетки, где он ниже: там выше концентрация растворённых веществ. Поэтому клетки набирают воду, и масса растёт. Одна контролируемая переменная — исходный размер цилиндров. Время погружения и температуру тоже сохраняй одинаковыми, а перед взвешиванием одинаково промокай каждый цилиндр.',4)],
 'b-nutrition':[q('enzyme','Explain why amylase activity rises with temperature to an optimum and then falls sharply. State what bile does.','Почему активность амилазы растёт до оптимума, а затем резко падает? Какова роль желчи?','Higher temperature initially increases successful collisions. Excessive heat disrupts enzyme structure and active-site fit: denaturation. Bile emulsifies lipids, increasing surface area for lipase, and helps neutralise acidic contents; bile is not an enzyme.','Сначала нагревание повышает частоту эффективных столкновений. Сильный нагрев нарушает структуру фермента и активный центр — денатурация. Желчь эмульгирует жиры и помогает нейтрализовать кислое содержимое; она не фермент.',5)],
 'b-transport':[q('heart','Trace a red blood cell from the vena cava to the aorta, naming chambers, major vessels and exchange location.','Проследи путь эритроцита от полой вены до аорты: камеры, сосуды и место газообмена.','Vena cava → right atrium → right ventricle → pulmonary artery → lung capillaries (CO₂ out, O₂ in) → pulmonary vein → left atrium → left ventricle → aorta. Valves prevent backflow; the left ventricle generates pressure for systemic circulation.','Полая вена → правое предсердие → правый желудочек → лёгочная артерия → капилляры лёгких → лёгочная вена → левое предсердие → левый желудочек → аорта. В лёгких отдаётся CO₂ и поступает O₂. Клапаны препятствуют обратному току.',6)],
 'b-respiration':[q('exercise','Distinguish breathing from respiration. Explain increased breathing after intense exercise.','Отличи дыхательные движения от клеточного дыхания. Почему после интенсивной нагрузки дыхание остаётся учащённым?','Ventilation moves air; respiration releases usable energy through reactions in cells. After intense exercise, extra oxygen supports recovery, including lactate processing and restoration of stores. Aerobic respiration uses oxygen; human anaerobic glycolysis forms lactate with a smaller ATP yield.','Вентиляция перемещает воздух, клеточное дыхание обеспечивает получение АТФ в реакциях клетки. После нагрузки дополнительный кислород нужен для восстановления, включая обмен лактата и пополнение запасов. Анаэробный путь в мышцах даёт меньше АТФ.',5)],
 'b-plants':[q('potometer','A bubble moves 24 mm in 4 min through a tube of radius 0.5 mm. Calculate water-uptake rate. Give one reason it is not an exact transpiration rate.','Пузырёк прошёл 24 мм за 4 мин в трубке радиусом 0,5 мм. Найди объёмную скорость и объясни приближённость оценки транспирации.','Volume = π×0.5²×24 = 18.85 mm³. Rate ≈4.71 mm³/min. Some water is retained or used in growth/photosynthesis; uptake does not exactly equal evaporation. A leak would additionally invalidate the measurement.','V = π×0,5²×24 ≈18,85 мм³; скорость ≈4,71 мм³/мин. Часть воды остаётся в растении и расходуется на рост и реакции. Утечка отдельно нарушит измерение.',5)],
 'b-disease':[q('resistance','Explain how antibiotic resistance becomes more common after antibiotic use and how vaccination differs.','Как использование антибиотика увеличивает долю устойчивых бактерий? Чем отличается вакцинация?','Variation in resistance exists or arises by mutation/gene transfer. Antibiotic selects: susceptible bacteria are removed; resistant survivors reproduce and pass on resistance. Bacteria do not deliberately adapt because they need to. Vaccination stimulates specific immune memory; antibiotics target susceptible bacteria and do not treat viruses directly.','Устойчивость возникает вследствие генетических изменений или передачи генов. Антибиотик отбирает устойчивые варианты: чувствительные погибают, выжившие размножаются. Бактерии не изменяются целенаправленно «по необходимости». Вакцина формирует специфическую иммунную память; антибиотик действует на чувствительные бактерии.',6)],
 'b-evolution':[q('selection','Compare natural selection with selective breeding. Why might breeding for one feature increase a disadvantage?','Сравни естественный отбор с искусственным. Почему отбор по одному признаку может усилить недостаток?','Natural selection reflects differential reproductive success in an environment; breeders choose parents for desired traits. Repeated use of related parents can reduce genetic diversity and increase expression of harmful recessive alleles. Link advantage to context rather than saying an organism is simply “more evolved”.','При естественном отборе различается репродуктивный успех в данной среде; при искусственном родителей выбирает человек. Скрещивание близких родственников может уменьшать разнообразие и повышать проявление вредных рецессивных аллелей. Преимущество всегда зависит от условий.',5)],
 'b-environment':[q('eutrophication','Explain the chain from fertiliser runoff to fish deaths. Give an intervention and a limitation.','Построй цепочку от стока удобрений до гибели рыб. Предложи меру и её ограничение.','Nutrients increase algal growth; shading and death add organic material; decomposers respire and consume dissolved oxygen; hypoxia harms fish. Buffer strips or reduced fertiliser runoff can help, but stored nutrients and other sources can delay recovery.','Избыток биогенных веществ усиливает рост водорослей. Отмирание и разложение органики увеличивают потребление растворённого кислорода; его дефицит вредит рыбам. Защитные полосы и уменьшение стока помогают, но накопленные вещества и другие источники задерживают восстановление.',6)],
 'b-biotech':[q('insulin','Outline how bacteria can be engineered to produce human insulin. Compare genome mapping with sequencing.','Опиши получение человеческого инсулина с помощью бактерий. Отличи картирование генома от секвенирования.','Introduce an appropriate insulin-coding sequence into a vector and host bacteria, select successful cells, culture under controlled conditions, then extract and purify the product. Mapping locates genetic features; sequencing determines nucleotide order. Production requires more than merely inserting DNA.','Кодирующую последовательность включают в вектор и вводят в бактерии; отбирают нужные клетки, выращивают культуру, извлекают и очищают продукт. Картирование определяет расположение генетических объектов, секвенирование — порядок нуклеотидов. Одного включения ДНК недостаточно для готового препарата.',6)],
 'b-nervous':[q('near','A student shifts focus from a distant wall to a nearby book. Describe accommodation and distinguish it from pupil constriction.','Ученик переводит взгляд со стены на близкую книгу. Опиши аккомодацию и отличи её от сужения зрачка.','Ciliary muscle contracts, suspensory ligaments loosen, lens becomes more convex with greater refractive power. Pupil constriction regulates light through iris muscles; it is not the lens-focusing mechanism.','Ресничная мышца сокращается, связки ослабевают, хрусталик становится более выпуклым и сильнее преломляет. Зрачок регулируется мышцами радужки и меняет поток света, а не кривизну хрусталика.',5)],
 'b-hormones':[q('feedback','Explain the response to a rise in blood glucose after a meal. Then state the roles of FSH, LH and progesterone.','Объясни ответ на повышение глюкозы после еды. Затем назови роли ФСГ, ЛГ и прогестерона.','Pancreatic beta cells release insulin, promoting glucose uptake and storage; the fall reduces the original stimulus: negative feedback. FSH supports follicle development; an LH surge triggers ovulation; progesterone supports the uterine lining.','Бета-клетки поджелудочной выделяют инсулин, который способствует усвоению и запасанию глюкозы. Снижение глюкозы уменьшает исходный стимул — отрицательная обратная связь. ФСГ поддерживает развитие фолликула; выброс ЛГ запускает овуляцию; прогестерон поддерживает эндометрий.',6)],
 'b-earlier':[q('reproduction','Distinguish pollination, fertilisation and seed dispersal. Why does a germinating seed need oxygen before leaves are active?','Отличи опыление, оплодотворение и распространение семян. Зачем прорастающему семени кислород до развития листьев?','Pollination transfers pollen; fertilisation fuses gamete nuclei; dispersal moves the resulting seed. The embryo respires stored food to supply ATP for growth before sufficient photosynthesis begins.','Опыление переносит пыльцу, оплодотворение объединяет ядра гамет, распространение перемещает сформировавшееся семя. Зародыш расходует запасённые вещества при дыхании и получает АТФ для роста.',5),q('placenta','Explain placenta function and distinguish a ligament from a tendon.','Объясни функцию плаценты и отличи связку от сухожилия.','Placenta permits exchange of gases, nutrients and wastes between separate maternal/fetal circulations. It is not a perfect barrier. Ligaments connect bones; tendons transmit muscle force to bones.','Плацента обеспечивает обмен между раздельными кровотоками матери и плода и не является абсолютным барьером. Связки соединяют кости; сухожилия передают тягу мышц костям.',4)],
 'm-core':[q('proof','Prove that the sum of two odd integers is even. Then solve the inequality 3(2x − 1) ≤ 15.','Докажи, что сумма двух нечётных целых чисел — чётное число. Затем реши неравенство 3(2x − 1) ≤ 15.','Let the integers be 2m + 1 and 2n + 1, where m and n are integers. The sum is (2m + 1) + (2n + 1) = 2m + 2n + 2 = 2(m + n + 1). Since m + n + 1 is an integer, the sum is twice an integer, so it is even.\n\nInequality:\n1. Expand the bracket: 6x − 3 ≤ 15.\n2. Add 3: 6x ≤ 18.\n3. Divide by 6: x ≤ 3.\n\nAnswer: x ≤ 3. The value 3 is included.','Пусть числа — 2m + 1 и 2n + 1, где m и n — целые. Сумма: (2m + 1) + (2n + 1) = 2m + 2n + 2 = 2(m + n + 1). Число m + n + 1 целое, значит, сумма — удвоенное целое число, то есть чётное.\n\nНеравенство:\n1. Раскрыли скобки: 6x − 3 ≤ 15.\n2. Прибавили 3: 6x ≤ 18.\n3. Разделили на 6: x ≤ 3.\n\nОтвет: x ≤ 3, число 3 входит в решение.',6),q('sets','Of 30 students, 18 take music, 16 play sport and 8 do both. Calculate how many students take music only, play sport only, and do neither.','Из 30 учеников 18 занимаются музыкой, 16 — спортом, 8 — и тем и другим. Вычисли, сколько учеников занимаются только музыкой, только спортом и ни тем ни другим.','Start with the overlap: 8 students do both.\n1. Music only: 18 − 8 = 10 students.\n2. Sport only: 16 − 8 = 8 students.\n3. Music or sport: 10 + 8 + 8 = 26 students (or 18 + 16 − 8 = 26).\n4. Neither: 30 − 26 = 4 students.\n\nAnswer: music only 10 students, sport only 8 students, neither 4 students.','Начни с пересечения: 8 учеников занимаются и тем и другим.\n1. Только музыка: 18 − 8 = 10 учеников.\n2. Только спорт: 16 − 8 = 8 учеников.\n3. Хотя бы одно из занятий: 10 + 8 + 8 = 26 учеников (или 18 + 16 − 8 = 26).\n4. Ни тем ни другим: 30 − 26 = 4 ученика.\n\nОтвет: только музыка — 10 учеников, только спорт — 8 учеников, ни тем ни другим — 4 ученика.',4)],
 'm-algebra':[q('quadratic','Solve x²−5x+6=0 and identify the vertex of y=x²−5x+6.','Реши x²−5x+6=0 и найди вершину параболы.','Factor (x−2)(x−3)=0, so x=2 or 3. Axis x=2.5; y=6.25−12.5+6=−0.25. Vertex (2.5,−0.25).','(x−2)(x−3)=0, корни 2 и 3. Ось x=2,5; y=−0,25; вершина (2,5;−0,25).',5)],
 'm-geometry':[q('triangle','A right-angled triangle has legs of 6 cm and 8 cm. Calculate the hypotenuse and the size of the angle opposite the 6 cm leg. Give both answers to one decimal place.','Катеты (legs) прямоугольного треугольника равны 6 см и 8 см. Вычисли гипотенузу (hypotenuse) и угол, противолежащий катету 6 см. Оба ответа округли до десятых.','Hypotenuse: √(6² + 8²) = √100 = 10.0 cm. Angle θ opposite the 6 cm leg: tan θ = 6 ÷ 8 = 0.75, so θ = tan⁻¹(0.75) ≈ 36.9°. On the calculator, use the tan⁻¹ key in degree mode (DEG).','Гипотенуза: √(6² + 8²) = √100 = 10,0 см. Угол θ напротив катета 6 см: tg θ = 6 ÷ 8 = 0,75, поэтому θ = arctg 0,75 ≈ 36,9°. На калькуляторе используй клавишу tg⁻¹ в режиме градусов (DEG).',4)],
 'm-data':[q('probability','A bag contains 3 red and 2 blue counters. Draw two without replacement. Find P(both red). Compare mean and median for 2,3,3,4,18.','В мешке 3 красных и 2 синих жетона. Достают два без возвращения. Найди P(оба красные). Сравни среднее и медиану чисел 2,3,3,4,18.','P=3/5×2/4=3/10. Mean=30/5=6; median=3. The high value pulls the mean upwards more strongly.','P=3/5×2/4=3/10. Среднее 6, медиана 3. Большое значение сильнее влияет на среднее.',5)],
 'g-tectonics':[q('vulnerability','Explain why earthquakes of similar magnitude can have very different impacts. Use two named case studies from this topic.','Объясни, почему землетрясения близкой магнитуды могут иметь очень разные последствия. Используй два названных случая из этой темы.','Compare exposure, depth, distance, building quality, governance, preparedness and access. The 1906 San Francisco earthquake (San Andreas Fault) and the Himalayan collision zone (thrust-fault earthquakes and slope hazards) illustrate different vulnerability and response conditions; do not attribute losses to magnitude alone. Support each comparison with the case facts in the lesson, and distinguish immediate effects from longer-term effects.','Сопоставь экспозицию, глубину, расстояние, здания, подготовку, управление и доступность помощи. Землетрясение 1906 года в Сан-Франциско (разлом Сан-Андреас) и Гималаи с их надвиговыми землетрясениями и оползнями различаются по уязвимости и условиям реагирования; потери нельзя объяснять одной магнитудой. Подкрепи сравнение фактами урока; отдели первичные последствия от долгосрочных.',8)],
 'g-previous':[q('fieldwork','Design a fair investigation into how river velocity changes downstream. Explain how you would measure velocity, choose sites and keep the measurements comparable. State one limitation and one improvement.','Спроектируй исследование того, как скорость реки меняется вниз по течению. Объясни, как будешь измерять скорость, выбирать точки и делать измерения сопоставимыми. Назови одно ограничение и одно улучшение.','First, choose several safe sites spaced along the river, from source to mouth. At each site, measure the same quantity, such as mean velocity, at several positions across the channel. Record depth, width and recent rainfall so that the sites can be compared.\n\n**Limitation:** timing a float mainly gives surface velocity, and wind can bias the result.\n\n**Improvement:** a calibrated flowmeter at standard depths gives a better estimate of mean velocity.\n\nOne site cannot describe the whole river, so compare several sites before drawing a conclusion.','Сначала выбери несколько безопасных точек вдоль реки от истока к устью. В каждой точке измеряй одну и ту же величину, например среднюю скорость, в нескольких местах поперёк русла. Записывай глубину, ширину и недавние осадки, чтобы точки можно было сравнить.\n\n**Ограничение:** замер времени поплавка в основном даёт поверхностную скорость, и ветер может исказить результат.\n\n**Улучшение:** откалиброванный измеритель скорости течения (flowmeter) на стандартных относительных глубинах даёт лучшую оценку средней скорости.\n\nОдна точка не описывает всю реку, поэтому перед выводом сравни несколько участков.',6)],
 'e-analysis':[q('comparison','Using the original Text A and the storyboard below, compare how each presents Mara’s attitude to the experiment. Write two comparative paragraphs.','По авторскому тексту A и раскадровке (storyboard) ниже сравни, как каждый материал показывает отношение Мары к эксперименту. Напиши два сравнительных абзаца.','A strong answer links both texts in every paragraph. First, make a claim about Mara’s attitude. Then give precise evidence from Text A, such as the hand she withdraws from the brass handle, and analyse one language choice and its effect. Next, give evidence from the storyboard and analyse one framing or sound choice and its effect. Finally, make a comparative judgement: say whether the texts are similar or different, and why.\n\nIn Text A, the hand she withdraws and the question written in the margin suggest doubt. In the storyboard, a closer frame or a delayed sound can turn that doubt into visible tension. Explain the effect on the audience, and do not retell the plot.','Сильный ответ связывает оба материала в каждом абзаце. Сначала сформулируй тезис (claim) об отношении Мары к эксперименту. Затем приведи точную деталь текста A, например руку, которую она отдёргивает от латунной ручки, и проанализируй один языковой выбор и его эффект. Далее приведи деталь из раскадровки и проанализируй один выбор композиции кадра (framing) или звука и его эффект. В конце сделай сопоставительный вывод: что сходно или различно и почему.\n\nВ тексте A рука, которую она отдёргивает, и вопрос на полях передают сомнение. В раскадровке более крупный кадр или задержанный звук могут превратить это сомнение в видимое напряжение. Объясни воздействие на зрителя и не пересказывай сюжет.',10)],
 'e-creative':[q('monologue','Write a 350–450-word monologue: a young inventor must decide whether to switch on a machine while a younger sibling waits outside. Show a change in their thinking; include purposeful stage directions. Timing: about 9 minutes (confirm the time with your teacher).','Напиши монолог на английском языке, 350–450 слов: юный изобретатель решает, включать ли машину, пока за дверью ждёт младший брат или сестра. Покажи, как меняется мысль героя, и добавь ремарки с понятной целью. Ориентир по времени: 9 минут (уточни время у учителя).','Check your monologue in this order.\n\n**Length**: 350–450 words.\n\n**Voice and audience**: the voice is distinct, and the listener is clear (the sibling, the audience or themselves).\n\n**Conflict**: the speaker wants something, and something stands in the way.\n\n**Shift**: the change in thinking is controlled, not random mood swings. A possible arc is confidence → imagined consequence → decision to delay and explain.\n\n**Stage directions**: each one can be performed, and each has a clear purpose.\n\n**Language and pacing**: word choice is precise, and pauses and sentence length control the pace.','Проверь монолог по шагам.\n\n**Объём**: 350–450 слов.\n\n**Голос и адресат**: голос узнаваем, и понятно, к кому герой обращается: к собеседнику, зрителю или к себе.\n\n**Конфликт**: герой чего-то хочет, и ему что-то мешает.\n\n**Поворот**: мысль меняется обдуманно, а не от случайных смен настроения. Возможная дуга: уверенность → воображаемые последствия → решение отложить опыт и объяснить.\n\n**Ремарки**: каждую может выполнить актёр, и у каждой есть цель.\n\n**Язык и темп**: слова точные, а паузы и длина фраз задают темп.',15)],
 'e-purpose':[q('speech','Write a 300–400 word speech to students arguing whether surveillance cameras should be used in school corridors. Acknowledge a counterargument and propose conditions.','Напиши английскую речь 300–400 слов для учеников о камерах наблюдения в коридорах школы. Рассмотри возражение и предложи условия использования.','Possible structure: specific scenario; position; two developed reasons; fair counterargument about privacy; proportionate safeguards such as limited access and retention; clear closing appeal. Do not invent statistics. Assess coherence, audience/register, evidence and language accuracy; disagreement with the sample position is allowed.','Возможная структура: ситуация, позиция, два развитых довода, возражение о приватности, условия доступа и хранения, финальный призыв. Не придумывай статистику. Оцени связность, адресата, аргументы и язык; позиция может отличаться от образца.',15)],
 'f-listen':[q("f-listen-comparatif","Complete each sentence so that it matches the meaning in brackets. Write the missing comparison word (plus, moins or aussi) and que. In sentence 4, write the comparative form of bon.\n\n1. Mara est ___ grande ___ Sam. (Mara is taller than Sam.)\n2. Ce film est ___ intéressant ___ le livre. (This film is less interesting than the book.)\n3. Mon frère est ___ sportif ___ moi. (My brother is as sporty as me.)\n4. Cette soupe est ___ que celle d’hier. (This soup is better than yesterday’s.)","Заполни пропуски. Смысл каждого пункта — в скобках. Впиши слово сравнения (plus, moins или aussi) и que. В пункте 4 впиши сравнительную форму от bon.\n\n1. Mara est ___ grande ___ Sam. (Мара выше Сэма.)\n2. Ce film est ___ intéressant ___ le livre. (Этот фильм менее интересен, чем книга.)\n3. Mon frère est ___ sportif ___ moi. (Мой брат такой же спортивный, как я.)\n4. Cette soupe est ___ que celle d’hier. (Этот суп лучше вчерашнего.)","1. plus … que: Mara est plus grande que Sam (Mara is taller than Sam). 2. moins … que: Ce film est moins intéressant que le livre (This film is less interesting than the book). 3. aussi … que: Mon frère est aussi sportif que moi (My brother is as sporty as me). 4. meilleure: Cette soupe est meilleure que celle d’hier (This soup is better than yesterday’s). Rule: the comparative is plus / moins / aussi + adjective + que. The adjective agrees with the noun (grande, meilleure). The comparative of bon is meilleur(e), not ‘plus bon’.","1. plus … que: Mara est plus grande que Sam («Мара выше Сэма»). 2. moins … que: Ce film est moins intéressant que le livre («Фильм менее интересный, чем книга»). 3. aussi … que: Mon frère est aussi sportif que moi («Мой брат такой же спортивный, как я»). 4. meilleure: Cette soupe est meilleure que celle d’hier («Этот суп лучше вчерашнего»). Правило: сравнительная степень (comparatif) строится как plus, moins или aussi + прилагательное + que. Прилагательное согласуется с существительным: grande, meilleure. От bon сравнительная степень — meilleur(e), не «plus bon».",4),q("f-listen-cependant","Complete each sentence with mais or cependant: use cependant in sentences 1 and 3, mais in sentence 2. Add a comma where it is needed.\n\n1. Le film était long. ___ il était très drôle.\n2. Léa voulait sortir, ___ il pleuvait.\n3. Le restaurant est petit ; ___ la cuisine est excellente.","Заполни пропуски словами mais или cependant: в пунктах 1 и 3 — cependant, в пункте 2 — mais. Поставь запятую там, где она нужна.\n\n1. Le film était long. ___ il était très drôle.\n2. Léa voulait sortir, ___ il pleuvait.\n3. Le restaurant est petit ; ___ la cuisine est excellente.","1. Cependant, il était très drôle (However, it was very funny). 2. Léa voulait sortir, mais il pleuvait (Léa wanted to go out, but it was raining). 3. Le restaurant est petit ; cependant, la cuisine est excellente (The restaurant is small; however, the food is excellent). Rule: cependant (‘however’) usually starts a sentence or follows a semicolon, with a comma after it. Mais (‘but’) joins two clauses in one sentence (Léa wanted to go out, but it was raining) or starts a new sentence (Mais il était très drôle). No comma after mais. A comma alone cannot join two complete sentences.","1. Cependant, il était très drôle («Однако он был очень смешным»). 2. Léa voulait sortir, mais il pleuvait («Леа хотела выйти, но шёл дождь»). 3. Le restaurant est petit ; cependant, la cuisine est excellente («Ресторан маленький; однако кухня отличная»). Правило: однако (cependant) обычно стоит в начале предложения или после точки с запятой, после него — запятая. Но (mais) соединяет две части предложения или начинает новое предложение; после него запятой нет. Не путай: запятой нельзя соединить два полных предложения.",3),q("f-listen-meme-si","Complete each sentence with même si. Before il or ils, write même s’. Then state the tense of the verb after même si: présent, passé composé or imparfait.\n\n1. Nous sortons ___ il pleut. Tense: ___\n2. Léa a continué à courir ___ elle était fatiguée. Tense: ___\n3. Sam a fait ses devoirs ___ il a eu une longue journée. Tense: ___","Заполни пропуски словами même si. Перед il или ils пиши même s’. Затем укажи время глагола после même si: présent, passé composé или imparfait.\n\n1. Nous sortons ___ il pleut. Время: ___\n2. Léa a continué à courir ___ elle était fatiguée. Время: ___\n3. Sam a fait ses devoirs ___ il a eu une longue journée. Время: ___","1. même s’il pleut: présent (pleut). 2. même si elle était fatiguée: imparfait (était). 3. même s’il a eu une longue journée: passé composé (a eu). Rule: même si (‘even though’) takes the indicative: présent, passé composé, imparfait or futur. It never takes the subjunctive. Before il or ils, si becomes s’. Do not confuse it with hypothetical si + imparfait + conditionnel, which needs a conditional in the main clause; these main clauses do not use one.","1. même s’il pleut — настоящее время (présent: pleut). 2. même si elle était fatiguée — имперфект (imparfait: était). 3. même s’il a eu une longue journée — сложное прошедшее (passé composé: a eu). Правило: даже если, хотя (même si) стоит с изъявительным наклонением (indicatif: présent, passé composé, imparfait, futur), а не с сослагательным (subjonctif). Перед il и ils si сокращается: même s’il. Не путай с условными предложениями si + imparfait: там в главной части условное наклонение (conditionnel).",6),q("f-listen-futur-simple","Transform each sentence. If it uses the futur proche, write the futur simple. If it uses the futur simple, write the futur proche.\n\n1. Ils vont envoyer les lettres demain.\n2. Nous ferons le projet ce week-end.\n3. Je vais être en France en juillet.","Перепиши каждое предложение. Если в нём ближайшее будущее (futur proche), запиши простое будущее (futur simple). Если в нём простое будущее, запиши ближайшее будущее.\n\n1. Ils vont envoyer les lettres demain.\n2. Nous ferons le projet ce week-end.\n3. Je vais être en France en juillet.","1. Ils enverront les lettres demain. 2. Nous allons faire le projet ce week-end. 3. Je serai en France en juillet. Rule: futur proche = present of aller + infinitive (vont envoyer). Futur simple = stem + endings -ai, -as, -a, -ons, -ez, -ont (ils enverront). Irregular stems: envoyer → enverr-, faire → fer-, être → ser-. Regular -er verbs keep the infinitive as the stem (parler → parlerai); -re verbs drop the final -e (prendre → prendr-).","1. Ils enverront les lettres demain («Они пришлют письма завтра»). 2. Nous allons faire le projet ce week-end («Мы собираемся сделать проект на этих выходных»). 3. Je serai en France en juillet («Я буду во Франции в июле»). Правило: ближайшее будущее (futur proche) — это aller в настоящем времени + инфинитив. Простое будущее (futur simple) — основа + окончания -ai, -as, -a, -ons, -ez, -ont. Неправильные основы: envoyer → enverr-, faire → fer-, être → ser-. Глаголы на -er берут инфинитив как основу (parler → parlerai); у глаголов на -re отбрасывается -e (prendre → prendr-).",3),q("f-listen-sante","Read the text and answer the questions in English.\n\nLéa veut avoir un style de vie sain. Elle mange des fruits et des légumes tous les jours. Avant, elle mangeait souvent des chips et buvait souvent des sodas. Maintenant, elle prépare ses repas et fait du sport trois fois par semaine. Sam, son frère, préfère la malbouffe, mais il commence à changer ses habitudes. Selon Léa, une alimentation saine et le sport sont importants pour la santé.\n\n1. What did Léa eat before, and what does she eat now?\n2. According to Léa, what is important for health?","Прочитай текст и ответь на вопросы по-английски.\n\nLéa veut avoir un style de vie sain. Elle mange des fruits et des légumes tous les jours. Avant, elle mangeait souvent des chips et buvait souvent des sodas. Maintenant, elle prépare ses repas et fait du sport trois fois par semaine. Sam, son frère, préfère la malbouffe, mais il commence à changer ses habitudes. Selon Léa, une alimentation saine et le sport sont importants pour la santé.\n\n1. Что Леа ела раньше и что ест сейчас?\n2. Что, по мнению Леа, важно для здоровья?","1. Before, she often ate chips and drank sodas; now she eats fruit and vegetables every day. 2. A healthy diet and sport.","1. Раньше она часто ела чипсы и пила газировку; сейчас ест фрукты и овощи каждый день. 2. Здоровое питание и спорт.",4),q("f-listen-solidarite","Read the text and answer the questions in English.\n\nAlex et Mara sont membres d’une association de quartier. Chaque samedi, ils aident les personnes âgées à faire leurs courses. Mara dit que la solidarité commence par de petits gestes. Alex a proposé un projet pour collecter des vêtements pour une association mondiale. Le projet a déjà aidé vingt familles. Alex pense que chacun peut être solidaire, même à l’école.\n\n1. What do Alex and Mara do every Saturday?\n2. What has Alex’s project achieved so far?","Прочитай текст и ответь на вопросы по-английски.\n\nAlex et Mara sont membres d’une association de quartier. Chaque samedi, ils aident les personnes âgées à faire leurs courses. Mara dit que la solidarité commence par de petits gestes. Alex a proposé un projet pour collecter des vêtements pour une association mondiale. Le projet a déjà aidé vingt familles. Alex pense que chacun peut être solidaire, même à l’école.\n\n1. Что Алекс и Мара делают каждую субботу?\n2. Чего уже добился проект Алекса?","1. They help elderly people with their shopping. 2. It has already helped twenty families. (The project collects clothes for a global association.)","1. Они помогают пожилым людям с покупками. 2. Проект уже помог двадцати семьям: он собирает одежду для мировой ассоциации.",4),q("f-listen-vacances","Read the text and answer the questions in English.\n\nCet été, Mara et sa famille ont fait des vacances à la montagne. Ils sont allés en train, car c’est plus écologique que l’avion. Le matin, Mara faisait de la randonnée avec son père. Sa mère préfère les vacances à la plage, mais cette année, elle a changé d’avis. Mara pense que le tourisme de masse est un problème, car les endroits célèbres sont trop pleins.\n\n1. How did the family travel to the mountains, and why?\n2. Why does Mara think mass tourism is a problem?","Прочитай текст и ответь на вопросы по-английски.\n\nCet été, Mara et sa famille ont fait des vacances à la montagne. Ils sont allés en train, car c’est plus écologique que l’avion. Le matin, Mara faisait de la randonnée avec son père. Sa mère préfère les vacances à la plage, mais cette année, elle a changé d’avis. Mara pense que le tourisme de masse est un problème, car les endroits célèbres sont trop pleins.\n\n1. Как семья добиралась в горы и почему?\n2. Почему Мара считает массовый туризм (le tourisme de masse) проблемой?","1. By train, because it is more ecological than flying. 2. Because famous places are too crowded.","1. На поезде, потому что это экологичнее самолёта. 2. Потому что известные места слишком переполнены.",4),q("f-listen-education","Read the text and answer the questions in English.\n\nLéa présente son école. Les cours commencent à huit heures. Le matin, les élèves ont souvent des maths et du français. Sam pense que l’école du futur utilisera plus d’ordinateurs. Selon lui, chaque enfant a le droit à l’éducation. Alex est d’accord avec Sam, mais il pense que les cours seront plus pratiques.\n\n1. When do lessons start at Léa’s school?\n2. What does Alex think about the school of the future?","Прочитай текст и ответь на вопросы по-английски.\n\nLéa présente son école. Les cours commencent à huit heures. Le matin, les élèves ont souvent des maths et du français. Sam pense que l’école du futur utilisera plus d’ordinateurs. Selon lui, chaque enfant a le droit à l’éducation. Alex est d’accord avec Sam, mais il pense que les cours seront plus pratiques.\n\n1. Во сколько начинаются уроки в школе Леа?\n2. Что Алекс думает о школе будущего?","1. At eight o’clock. 2. He agrees with Sam, but thinks lessons will be more practical.","1. В восемь часов. 2. Он согласен с Сэмом, но думает, что уроки будут более практичными.",4),q("f-listen-film","Read the text and answer the questions in English.\n\nHier, la classe de Mara a regardé le film « Le Dernier Autobus ». Pendant le film, Sam a pris des notes. Après la séance, Léa a proposé une discussion sur le droit à l’éducation. Selon elle, le film l’a fait réfléchir. Mara pense que la classe pourra présenter ses idées la semaine prochaine.\n\n1. What did Mara’s class do yesterday?\n2. What does Léa propose after the film?","Прочитай текст и ответь на вопросы по-английски.\n\nHier, la classe de Mara a regardé le film « Le Dernier Autobus ». Pendant le film, Sam a pris des notes. Après la séance, Léa a proposé une discussion sur le droit à l’éducation. Selon elle, le film l’a fait réfléchir. Mara pense que la classe pourra présenter ses idées la semaine prochaine.\n\n1. Что сделал класс Мары вчера?\n2. Что предлагает Леа после фильма?","1. They watched the film ‘Le Dernier Autobus’ (literally ‘The Last Bus’). 2. A discussion about the right to education.","1. Класс посмотрел фильм «Le Dernier Autobus» (буквально «Последний автобус»). 2. Обсуждение права на образование.",4)],
 'f-write':[q('blog','Écrivez un billet de blog de 120–150 mots: comment utilisez-vous la technologie? Incluez un avantage, un risque, une expérience passée et un conseil.','Напиши блог по-французски 120–150 слов об использовании технологий: преимущество, риск, прошлый опыт и совет.','Check all four content points, clear paragraphs, appropriate blog voice, justified opinions, a past-tense sentence and an accurate recommendation. Example opening: «La technologie m’aide à apprendre, mais je dois aussi savoir me déconnecter.» Extend with your own details rather than memorising one whole answer.','Проверь все четыре пункта, абзацы, стиль блога, обоснованное мнение, прошлое время и совет. Возможное начало: «La technologie m’aide à apprendre, mais je dois aussi savoir me déconnecter.» Дальше добавь свои детали; не заучивай один текст целиком.',12)],
 'f-language':[q('tenses','Complete and explain: Si j’___ (avoir) plus de temps, je ___ (lire) davantage. Il faut que nous ___ (faire) attention. Quand je suis arrivé, elle ___ déjà ___ (partir).','Заполни формы и объясни: Si j’___ (avoir) plus de temps, je ___ (lire) davantage. Il faut que nous ___ (faire) attention. Quand je suis arrivé, elle ___ déjà ___ (partir).','Si j’avais plus de temps, je lirais davantage: imparfait + conditionnel. Il faut que nous fassions attention: subjonctif. Elle était déjà partie: plus-que-parfait with être and feminine agreement.','avais / lirais: imparfait + conditionnel. fassions: subjonctif после il faut que. était déjà partie: plus-que-parfait с être и согласованием в женском роде.',6)],
 'a-language':[q('arabic','If Arabic is on your registered timetable, write a short message introducing yourself, describing your school routine and asking a question. Use the vocabulary and grammar below.','Если арабский есть в личном расписании, напиши короткое сообщение: представься, опиши школьный день, задай вопрос. Используй словарь и грамматику ниже.','Self-check agreement, verb/person, word order, question form and register. The school’s current Arabic level and November topic list have not been verified; adapt length and content with your teacher.','Проверь согласование, лицо глагола, порядок слов, вопрос и регистр. Текущий уровень и ноябрьский список арабского не подтверждены; объём и содержание согласуй с учителем.')],
 's-b':[q('design','Design an investigation into how acid concentration affects the rate of magnesium reacting with hydrochloric acid. Use equal volumes and measure gas volume over time.','Спроектируй исследование влияния концентрации HCl на скорость реакции с магнием. Объём кислоты одинаковый; измеряй объём газа со временем.','Question names concentration and initial hydrogen-production rate. Predict more frequent effective collisions at higher concentration. Use at least five concentrations, same Mg mass/surface preparation, acid volume and temperature, an airtight gas syringe, timed readings, three repeats and a defined initial-slope calculation. Check acid is in excess for all trials. Wear goggles; keep hydrogen away from ignition; do not seal a gas-producing reaction without a safe gas outlet.','Вопрос связывает концентрацию с начальной скоростью выделения H₂. Гипотеза объясняется столкновениями. Возьми хотя бы пять концентраций; одинаковые массу и поверхность Mg, объём и температуру кислоты; герметичный газовый шприц, интервалы времени, три повтора и расчёт начального наклона. Проверь избыток кислоты во всех опытах. Очки; водород вдали от огня; газ должен иметь безопасный выход.',10)],
 's-c':[q('analyse','At 20, 30, 40, 50°C, enzyme rates are 1.2, 2.1, 3.0, 0.8 units/min. Describe, explain and evaluate the claim “rate is directly proportional to temperature”.','При 20, 30, 40, 50 °C скорости фермента 1,2; 2,1; 3,0; 0,8 ед/мин. Опиши, объясни и оцени утверждение «скорость прямо пропорциональна температуре».','Rate rises to 40°C in the tested data, then falls; the optimum is not located exactly without closer sampling. Increased collisions initially help; denaturation can explain the fall. The whole dataset is not directly proportional: it falls at 50°C and ratios are not constant. Repeat trials, report spread and add temperatures around the peak; control pH and concentrations.','Рост до 40 °C, затем падение; точный оптимум без дополнительных точек неизвестен. Сначала помогают столкновения, затем возможна денатурация. Прямой пропорциональности нет: при 50 °C спад, отношения непостоянны. Нужны повторы, разброс, точки около максимума и контроль pH и концентраций.',8)],
 's-d':[q('evaluate','A fictional town compares buses: diesel £200k purchase/£60k annual operation; electric £320k/£35k. Electric buses remove exhaust at the street but battery manufacture and electricity generation have impacts. Give a five-year cost comparison and an evidence-based recommendation.','В условном городе дизельный автобус стоит £200 тыс. и £60 тыс./год, электрический £320 тыс. и £35 тыс./год. У электрического нет выхлопа на улице, но производство батареи и электроэнергии влияет на среду. Сравни стоимость за 5 лет и обоснуй решение.','Diesel: 200+5×60=£500k; electric: 320+5×35=£495k, excluding financing, infrastructure and residual value. The small £5k difference is not decisive. Consider local air quality, electricity mix, charging capacity, battery life and uncertainty. A conditional recommendation is stronger than claiming electric buses have zero environmental impact. These are invented practice data.','Дизель: £500 тыс.; электрический: £495 тыс. без инфраструктуры, финансирования и остаточной стоимости. Разница £5 тыс. мала. Учти воздух на улицах, энергосистему, зарядку, срок батареи и неопределённость. Обоснован условный вывод; утверждение «воздействия нет» неверно. Числа придуманы для учебного задания.',10)],
};

export const englishStimulus = b('The notebook lay open beside the switch. All winter, Mara had imagined this moment as a door opening. Now she could hear her brother on the other side of the laboratory wall, humming the tune she had taught him. She touched the brass handle, then withdrew her hand. The machine answered with a small, patient click. For the first time, she wrote a question in the margin instead of a result: Who gets to decide what happens next?', 'Тетрадь лежала открытой рядом с выключателем. Всю зиму Мара представляла этот момент как открывающуюся дверь. Теперь она могла слышать, как её брат по другую сторону лабораторной стены напевает мелодию, которой она его научила. Она коснулась латунной ручки, а потом отдёрнула руку. Машина ответила негромким, терпеливым щелчком. Впервые вместо результата она написала на полях вопрос: «Кто вправе решать, что будет дальше?»');
export const storyboard = [
 b('Shot 1: wide shot of an empty laboratory; a steady electrical hum. Mara is small in the frame.','Кадр 1: общий план (wide shot) пустой лаборатории, ровное гудение. Мара занимает мало места в кадре.'),
 b('Shot 2: close-up of a finger above the switch. The hum stops; the brother’s humming is heard off-screen.','Кадр 2: крупный план (close-up) пальца над выключателем. Гудение обрывается, за кадром слышно, как напевает брат.'),
 b('Shot 3: cut to Mara’s face, held for four seconds without speech. Her eyes move towards the door.','Кадр 3: склейка (cut) на лицо Мары. Кадр держится четыре секунды без речи. Она переводит взгляд на дверь.'),
 b('Shot 4: close-up of the notebook. She writes the question, closes the book and steps away. A single click follows the cut to black.','Кадр 4: крупный план тетради. Мара пишет вопрос, закрывает её и отходит. После склейки на чёрный кадр слышен один щелчок.'),
];

// Original tasks mirroring the skills in the school's 16-page November booklet.
practice['b-transport'].push(q('elastic-vessels','Design a model investigation comparing the stretch of two elastic tubes under equal loads. Explain what it can and cannot show about arteries and veins.','Спроектируй модель сравнения растяжения двух эластичных трубок при равных нагрузках. Что она показывает о сосудах, а что не доказывает?','Use the same starting length, wall geometry where possible, load steps and reference points; measure extension after settling, repeat and plot extension against force for each material. Tube material/type is the comparison variable; load is varied systematically for both. Arteries have adaptations for higher pressure, but a rubber model does not reproduce living tissue, smooth-muscle regulation or vessel pressure. Avoid mixing vessel type into the list of controls when it is the comparison being tested.','Сохраняй исходную длину, по возможности геометрию стенки, шаги нагрузки и точки отсчёта; после покоя измеряй удлинение, повторяй, строй зависимости для обоих материалов. Тип трубки — сравниваемая величина, нагрузку меняют одинаково. Модель не воспроизводит живую стенку, регуляцию мышц или давление крови. Тип сосуда нельзя объявить контролируемой переменной, если именно его сравнивают.',8));
practice['b-cells'].push(q('surface-volume','Compare a cube with a side of 1 cm and a cube with a side of 3 cm. Calculate the surface area to volume ratio of each cube. Use your results to predict which cube cools faster, and state one limitation of this prediction.','Сравни куб с ребром 1 см и куб с ребром 3 см. Вычисли отношение площади поверхности к объёму для каждого куба. По результатам предскажи, какой куб остынет быстрее, и назови одно ограничение этого прогноза.','1 cm cube: SA = 6 cm², V = 1 cm³; SA:V = 6/0.01 m = 600 m⁻¹. 3 cm cube: SA = 54 cm², V = 27 cm³; SA:V = 6/0.03 m = 200 m⁻¹. The smaller cube has more surface area for each unit of volume, so it loses more heat per unit of volume and cools faster. Shape, insulation, blood circulation and surroundings also affect temperature, so size alone does not decide how fast an animal cools.','Куб с ребром 1 см: SA = 6 см², V = 1 см³; SA:V = 6/0,01 м = 600 м⁻¹. Куб с ребром 3 см: SA = 54 см², V = 27 см³; SA:V = 6/0,03 м = 200 м⁻¹. У меньшего куба на единицу объёма приходится больше поверхности, поэтому он теряет больше тепла на единицу объёма и остывает быстрее. Форма, теплоизоляция, кровоток и среда тоже влияют на температуру, поэтому один размер не определяет, насколько быстро остывает животное.',6));
practice['b-nutrition'].push(q('sugar-test','How could you compare reducing-sugar content of five drinks using a calibrated school assay? Why is an ordinary Benedict’s colour test not a measurement of all dietary sugar?','Как сравнить восстанавливающие сахара пяти напитков калиброванной школьной пробой? Почему обычная цветная проба Бенедикта не измеряет весь пищевой сахар?','Use known glucose standards, identical dilution, sample/reagent volumes, heating temperature/time, repeats and an appropriate calibrated colour/precipitate measurement within its working range. Include blanks and control drink colour interference. Ordinary visual colours are at best semi-quantitative, non-reducing sugars may not react, and other reducing substances can interfere. Results cannot determine whether a drink is medically suitable for a person.','Нужны стандарты глюкозы, одинаковые разведения, объёмы, температура и время нагрева, повторы и калиброванное измерение в рабочем диапазоне. Учти окраску напитка и холостой образец. Визуальные цвета дают лишь приблизительную оценку; невосстанавливающие сахара могут не реагировать, другие восстановители мешают. Проба не устанавливает медицинскую пригодность напитка.',8));
practice['b-plants'].push(q('light-design','Design a pondweed photosynthesis investigation using five measured light intensities. Explain why counting bubbles and changing lamp distance are imperfect proxies.','Спроектируй опыт с водным растением и пятью измеренными интенсивностями света. Почему число пузырьков и расстояние до лампы — приближения?','Measure oxygen volume per time after acclimatisation; keep species/plant size, CO₂ supply and temperature controlled; use repeats and a heat shield/water bath where appropriate. Bubble sizes vary and gas dissolves; collect volume rather than only count. Lamp distance does not directly measure light intensity and the inverse-square model assumes an approximately point source and suitable geometry. Measure intensity with a sensor and keep heating controlled.','Измеряй объём O₂ за время после адаптации, сохраняй вид/размер растения, CO₂ и температуру; повторы и защита от нагрева. Пузырьки различаются по объёму, часть газа растворяется: лучше собирать объём. Расстояние не равно интенсивности; закон обратных квадратов требует подходящей геометрии и приближения точечного источника. Используй датчик света.',8));
practice['b-evolution'].push(q('clones','Invented cloning data: species X produces 200 embryos and 4 live offspring; species Y 300 embryos and 3 live offspring, in different laboratories. Compare success rates and evaluate “X clones more successfully”.','Условные данные клонирования: X — 200 эмбрионов, 4 живых потомка; Y — 300 и 3, в разных лабораториях. Сравни доли успеха и оцени вывод о преимуществе X.','X=4/200=2%; Y=3/300=1%. X has the higher observed proportion, but different laboratories, donor cells and surrogate conditions can confound a species effect. Small offspring counts and no repeat series limit confidence. Standardise procedures, use repeated independent batches and report variation; do not compare raw offspring counts alone. A somatic-cell nuclear clone shares the donor’s nuclear genotype, not necessarily identical mitochondria, environment or phenotype.','X=2%, Y=1%. Наблюдаемая доля X выше, но лаборатории, клетки и условия суррогатных матерей смешивают причины. Малые числа и отсутствие повторных серий ограничивают вывод. Стандартизируй процедуры, повторяй независимые серии, оцени разброс. Ядерный генотип клона не означает полностью одинаковые митохондрии, среду и фенотип.',8));
practice['b-nervous'].push(q('reaction-time','In a fictional ruler-drop test, mean catch distance falls from 20 cm to 16 cm after a drink. Explain why this alone does not show the drink caused faster reactions. How is catch distance converted to time?','В условном опыте с падающей линейкой средний путь до захвата уменьшился с 20 до 16 см после напитка. Почему причинность не доказана? Как путь переводят во время?','Practice, anticipation, order and fatigue may change results; use a suitable control, randomised/counterbalanced order, independent participants and repeats, subject to school consent and safety rules. Ruler drop is a coordinated response, not a pure spinal reflex. For ideal free fall from rest t=√(2d/g), using metres; with g=10, 0.20 m gives 0.20 s and 0.16 m gives about 0.179 s. Equal centimetre changes are not equal time changes. Do not ask anyone to consume caffeine for this practice task.','Мешают обучение, ожидание, порядок и усталость. Нужны контроль, чередование порядка, независимые участники и повторы с соблюдением школьных правил. Захват линейки — координированная реакция, не чистый спинальный рефлекс. t=√(2d/g), d в метрах; при g=10 получаются 0,20 и около 0,179 с. Равные сантиметры не равны одинаковому времени. Для этого задания кофеин употреблять не нужно.',8));
practice['b-respiration'].push(q('fermentation','Explain alcoholic fermentation in yeast and evaluate one industrial benefit against two limitations.','Объясни спиртовое брожение дрожжей и оцени промышленную пользу и два ограничения.','Without oxygen, yeast can regenerate NAD⁺ through fermentation so glycolysis can continue, forming ethanol and CO₂ with a small ATP yield. CO₂ raises bread dough; ethanol is used in beverages and some fuels. Control temperature and substrate concentration; contamination and product toxicity can reduce performance. Economic benefits must be weighed against energy/resource use and social harms where alcohol is consumed. Distinguish fermentation from aerobic respiration.','Без кислорода брожение восстанавливает NAD⁺ и позволяет продолжать гликолиз; образуются этанол и CO₂ при небольшом выходе АТФ. CO₂ разрыхляет тесто, этанол используют в напитках и топливе. Температура, субстрат, загрязнение и токсичность продукта влияют на выход. Пользу сопоставь с ресурсами и социальными последствиями употребления алкоголя. Это отличается от аэробного дыхания.',8));

// A complete timed response follows the school's 9 October Task 1e format.
practice['e-analysis'].push(q('task-1e-timed',
 'Timed rehearsal (about 35 minutes; confirm the time with your teacher). Using Text A and the storyboard, compare and contrast how the writer and the director present Mara’s responsibility for the experiment. Plan for about 5 minutes, write for about 25 and check for about 5. Write a complete response, linking both stimuli in each main paragraph.',
 'Тренировка на время (ориентир — 35 минут; уточни время у учителя). По тексту A и раскадровке сравни и сопоставь, как писатель и режиссёр показывают ответственность Мары за эксперимент. ориентировочно: 5 минут — план, 25 — написание ответа, 5 — проверка. Напиши полный ответ и в каждом основном абзаце связывай оба материала.',
 'Possible thesis: both stimuli move from apparent control towards doubt. Prose shows Mara’s private hesitation through her actions and her question in the margin, while the storyboard can make her responsibility visible through framing, objects and sound.\n\nOrganise two or three comparative claims, for example: control of the experiment, hesitation before action or responsibility to another person. For each claim, select a precise word or narrative detail from Text A and a shot, prop or sound detail from the storyboard. Explain how each choice creates meaning, then judge the similarity or difference.\n\nA weak sentence such as “The camera zooms in” names a technique only. Explain what becomes prominent, what is withheld and why this may change the viewer’s response.\n\nConclude by answering the question itself rather than listing techniques.\n\nSelf-check: balanced coverage of both stimuli, accurate evidence, explained language and film choices, a connected comparison, clear paragraph organisation and clear expression.\n\nThere is no single compulsory interpretation; justify yours.',
 'Возможный тезис: оба материала ведут от кажущегося контроля к сомнению. Проза показывает внутреннее колебание Мары через её поступки и вопрос на полях. Раскадровка может сделать её ответственность видимой через композицию кадра (framing), предметы и звук.\n\nПострой два-три сопоставительных утверждения, например: контроль над экспериментом, колебание перед действием или ответственность перед другим человеком. Для каждого тезиса выбери точное слово или повествовательную деталь из текста A и кадр, предмет или звуковую деталь из раскадровки. Объясни, как каждый выбор создаёт смысл, затем оцени сходство или различие.\n\nСлабая фраза вроде «Камера делает наезд» только называет приём. Объясни, что становится заметным, что остаётся скрытым и почему это может менять реакцию зрителя.\n\nВ выводе ответь на вопрос задания, а не перечисляй приёмы.\n\nСамопроверка: равное внимание обоим материалам, точные доказательства, объяснение языковых и кинематографических выборов, связное сравнение, ясная структура абзацев и ясное выражение мыслей.\n\nЕдинственной обязательной трактовки нет — обоснуй свою.'));
